window.SB_FILLS = {"006ff4bf8b4b6b2b":{"t":"work","blocks":[{"t":"ul","items":[{"en":"v. The beaker that turns milky is the one that holds a basic calcium compound, for example lime water: carbon dioxide makes white calcium carbonate that does not dissolve. Beaker with only water stays clear (it just becomes slightly acidic, carbonic acid)."},{"en":"vi. Other salts and bases that turn milky on passing CO₂: barium hydroxide solution (barium carbonate) and strontium hydroxide; with more CO₂ the milkiness clears again, as the carbonate changes to soluble hydrogencarbonate."},{"en":"Note: calcium chloride itself does not make the water milky (see the note under Activity 15.3)."}]}]},"03316072226b8006":{"t":"work","blocks":[{"t":"p","en":"Crushing is a physical change. Only the shape of the can changed; the aluminium did not become a new substance, and it can be melted and made into a can again."}]},"036bd4d82680ced2":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Crystalline solids at home","Amorphous solids at home"],["Table salt (sodium chloride)","Glass of windows and bottles"],["Sugar","Plastic bags and bottles"],["Ice","Rubber bands and tyres"],["Sand and quartz (silicon dioxide)","Candle wax"],["Washing soda and baking soda","Charcoal and coal"],["Alum (phitkari) and copper sulphate","Tar (bitumen) and chewing gum"],["Metals: copper wire, iron nails, aluminium foil","Silica gel in packets, dried glue"],["Diamond in jewellery","Plastic toys and wax crayons"]]},{"t":"p","en":"A crystalline solid has its particles in a regular repeating pattern, a sharp melting point and flat faces. An amorphous solid has its particles in no regular pattern and softens over a range of temperature before it melts."}]},"04f182a3be09d679":{"t":"table","rows":[["fox","foxes","brush","brushes"],["bench","benches","church","churches"],["dress","dresses","class","classes"],["glass","glasses","catch","catches"],["tax","taxes","lunch","lunches"]]},"057d8c1aeca8b876":{"t":"table","rows":[["played","wanted","jumped"],["cleaned","needed","walked"]]},"05c2a9f978a881c9":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Forest","Grassland","Pond","Desert","Snow"],["thick shrubs","grass","lotus","camel","penguin"],["tiger","antelope","fish","snake","polar bear"],["lion","sheep","frog","",""],["elephant, deer","goat","plant (water plant)","",""]]}]},"07ba931a5de0dd16":{"t":"work","blocks":[{"t":"p","en":"The candle flame can be seen only when the three holes and the flame are in one straight line. If one cardboard is moved a little, the flame is hidden. So light travels in a straight line."}]},"09355fdbc859b08d":{"t":"table","rows":[["Financial","Raja Todar Mal's land revenue system: land was measured and the tax fixed in cash from the average harvest; the jizya was abolished","Kept the land revenue system, re-imposed the jizya (1679) and gave up some old cesses; long wars emptied the treasury"],["Religious","Tolerance for all faiths (Sulh-e-Kul): the Ibadat Khana for religious talks; no tax on pilgrims","Followed the Sharia strictly: ended music at court and compiled the Fatawa-e-Alamgiri"],["Administrative","Mansabdari system: every officer had a rank (mansab); the empire was divided into subas, sarkars and parganas","Kept the same system, but there were too many mansabdars and too few jagirs, and the long wars in the Deccan stretched the administration"]]},"093c2cfbc2d05591":{"t":"work","blocks":[{"t":"p","en":"Bohr's theory (1913): electrons move around the nucleus only in fixed circular paths called shells or energy levels (K, L, M, N). An electron in a shell does not lose energy; it jumps to a higher shell when it takes in energy and falls back when it gives energy out as light. The shell number n can hold at most 2n² electrons: 2, 8, 18, 32."},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 214 214\" width=\"214\" role=\"img\" aria-label=\"Bohr model of Cl: 17 protons, 18 neutrons, shells 2, 8, 7\"><circle cx=\"107\" cy=\"107\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"107.0\" cy=\"53.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107.0\" cy=\"161.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"78\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"136.8\" cy=\"34.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"179.1\" cy=\"77.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"179.1\" cy=\"136.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"136.8\" cy=\"179.1\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"77.2\" cy=\"179.1\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"34.9\" cy=\"136.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"34.9\" cy=\"77.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"77.2\" cy=\"34.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"102\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"107.0\" cy=\"5.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"186.7\" cy=\"43.4\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"206.4\" cy=\"129.7\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"151.3\" cy=\"198.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"62.7\" cy=\"198.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"7.6\" cy=\"129.7\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"27.3\" cy=\"43.4\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"107\" y=\"103\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">17p</text><text x=\"107\" y=\"119\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">18n</text></svg>","cap":{"en":"Example model, chlorine-35: 17 protons and 18 neutrons in the nucleus; 17 electrons in the K, L and M shells (2, 8, 7)."}},{"t":"ul","items":[{"en":"Draw the nucleus in the middle and write the protons and neutrons in it."},{"en":"Draw one circle for each shell and label them K, L, M outwards."},{"en":"Put the electrons on the circles, filling K first (2), then L (8), then M."},{"en":"Write the atomic number, the mass number and the electron arrangement under the model and display it in the laboratory."}]}]},"09b50757b5652469":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["For the statement (agree)","Against the statement (disagree)"],["Fertilisers add nitrogen, phosphorus and potassium to the soil, so crops give a much larger yield.","Too much fertiliser washes into rivers and lakes (eutrophication) and harms fish and water plants."],["Without them the land would not feed the growing population, and more forest would be cleared for farms.","Nitrate in drinking water is harmful, especially for babies; fertilisers also add greenhouse gases (nitrous oxide)."],["They act quickly, are easy to store and apply, and their composition is known.","They cost money and make farmers depend on factories; they do not improve the soil's structure, as manure and compost do."],["Used in the right amount and at the right time, losses are small.","Better solutions together: manure, crop rotation with beans, using less food waste and less meat, and efficient use of fertiliser."]]},{"t":"p","en":"A balanced conclusion: artificial fertilisers are needed to feed the world, but 'best solution' is too strong; they work best together with careful use and natural methods."}]},"0d86d61a112e6506":{"t":"work","blocks":[{"t":"p","en":"A seed holds stored food. The baby plant lives on this food until its leaves grow and can make food for it (photosynthesis). So the plant first grows from the food of the seed, and later from the food made by its own leaves."}]},"0f18b11c611e7350":{"t":"table","rows":[["وادی","وادیاں"],["جنگل","جنگلات"],["چوٹی","چوٹیاں"],["ندی","ندیاں"],["کھنڈر","کھنڈرات"]]},"0f814d311ff390a4":{"t":"table","rows":[["Numbers divisible by 5","10, 30","25, 35, 45"],["Numbers not divisible by 5","18, 22, 48, 52","29, 37, 43"]]},"0fce696bbd6424a8":{"t":"work","blocks":[{"t":"p","en":"The drop of water on the plastic sheet curves outwards and works as a convex lens. A convex lens bends the light that passes through it, so a tiny object seen through it looks larger. Strong microscopes use glass lenses in the same way to show microorganisms that the eye cannot see."}]},"109ef645745972f8":{"t":"work","blocks":[{"t":"ul","items":[{"en":"A dark shape of the hand (its shadow) appears on the wall, because the hand is opaque and stops the light, and light travels in straight lines."},{"en":"Bring the hand near the candle: the shadow on the wall becomes bigger. Move the hand away from the candle (nearer the wall): the shadow becomes smaller and sharper."},{"en":"Inference: the closer an object is to the light source, the larger its shadow."}]}]},"10d60cbd213d526b":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Mango tree","Goat"],["Similarities","both are living: they need food, water and air, they grow, they reproduce and they react to their surroundings","the same"],["Differences","makes its own food in its leaves; stays in one place; has roots and leaves; no mouth or legs","eats plants for food; moves from place to place; has a mouth, legs and a backbone; breathes with lungs"]]}]},"11a6bf12bd847fdf":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Test tube","What is given","Result","Why"],["A","wet cotton: water and air","the seeds germinate","they have water, air and warmth"],["B","dry cotton: air only","no germination","no water"],["C","water with a layer of oil on top","no germination (or very little)","the oil keeps air away from the seeds"],["D","the seeds under water: water only","no germination (or very little)","there is not enough air"]]},{"t":"p","en":"Conclusion: seeds need water, air and a suitable temperature to germinate."}]},"11db150cf0cc9af6":{"t":"table","rows":[["Capt.","captain"],["dept.","department"],["govt.","government"],["Ltd.","limited"],["approx.","approximately"]]},"13a12f67477eec88":{"t":"work","blocks":[{"t":"p","en":"The suspended magnet comes to rest along the north-south direction. The Earth behaves like a huge magnet, with its magnetic poles near the geographic poles, and its magnetic field turns the suspended magnet."}]},"1479b8c348a63dd0":{"t":"table","rows":[["6","6","12","18","24","30","36","42","48","54","60"],["7","7","14","21","28","35","42","49","56","63","70"],["8","8","16","24","32","40","48","56","64","72","80"],["9","9","18","27","36","45","54","63","72","81","90"]]},"20be3afa7767d440":{"t":"work","blocks":[{"t":"p","en":"The volume of the water is the same in the glass as it was in the cup (if none is spilt): a liquid has a fixed volume."}]},"2237055b60f0b1fd":{"t":"table","rows":[["a.","K","19","19","19"],["b.","O","8","8","8"],["c.","P","15","15","15"],["d.","Ca","20","20","20"],["e.","Cl","17","17","17"]]},"22d99aa06435a02d":{"t":"table","rows":[["Date of Birth:","31 July 1893","Mother's Name:","Mithibai"],["Date of Death:","9 July 1967","Education:","Dentistry, at the dental college in Calcutta"],["Place of Birth:","Karachi","Occupation:","Dentist, social worker and political leader (Madar-e-Millat)"],["Father's Name:","Jinnahbhai Poonja","-","-"]]},"232bb5ba62ebc742":{"t":"table","rows":[["king","lioness","tree"],["uncle","milkmaid","chair"],["lion","niece","pencil"],["prince","goose","desk"]]},"23c33511c41cafc3":{"t":"table","rows":[["Carbohydrate","Carbon, hydrogen and oxygen","Monosaccharides (simple sugars such as glucose)","The main and quickest source of energy; stored as starch (plants) and glycogen (animals); cellulose gives plant cell walls their strength","Glucose, sucrose, starch, glycogen, cellulose","Rice, wheat, bread, potatoes, fruits, sugar, honey"],["Proteins","Carbon, hydrogen, oxygen and nitrogen (often sulphur)","Amino acids","Growth and repair of the body; enzymes, some hormones, antibodies, transport and muscle movement","Haemoglobin, keratin, insulin, collagen, enzymes such as amylase","Meat, fish, eggs, milk, pulses, nuts"],["Lipids","Carbon, hydrogen and oxygen (much less oxygen than carbohydrates)","Glycerol and fatty acids","Store energy (more than carbohydrates), insulate the body, protect organs and form cell membranes","Fats, oils, waxes, cholesterol, phospholipids","Butter, ghee, cooking oil, nuts, egg yolk, fatty meat"],["Nucleic acid","Carbon, hydrogen, oxygen, nitrogen and phosphorus","Nucleotides","Store and pass on genetic information and direct the making of proteins","DNA and RNA","Found in all living cells, so in all meat, vegetables and fruit"]]},"27803a41ab0bdba1":{"t":"table","rows":[["sruinvale","universal","of or for all; true everywhere"],["nitncae","ancient","very old; belonging to a time long ago"],["tlrueuc","culture","the customs, arts and way of life of a people"],["dnoiatitr","tradition","a custom or belief handed down from older people to younger ones"],["leuvas","values","the beliefs and principles that guide how people behave"],["sissaclc","classics","books or works of the highest quality that last through time"],["tanrorra","narrator","the person who tells a story"],["ruetunr","nurture","to care for someone and help them grow"],["tiaentern","entertain","to give pleasure or amusement"],["tomprlageu","promulgate","to make widely known; to announce publicly"]]},"2902b1c30cf35c72":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Battery","Advantages","Disadvantages"],["Lithium-ion (nickel-manganese-cobalt type)","Stores a lot of energy for its weight, so a long range; used in most electric cars; can be charged many hundreds of times.","Expensive (cobalt and nickel); can overheat and catch fire if damaged; wears out with age and heat."],["Lithium iron phosphate (LFP)","Safer, lasts for thousands of charges, cheaper, contains no cobalt or nickel.","Stores less energy for its weight, so a shorter range; weaker in cold weather."],["Nickel-metal hydride","Proven (used in hybrid cars), safe and long-lasting.","Heavier and stores less energy than lithium-ion; loses charge when standing."],["Lead-acid","Cheap, reliable and easy to recycle.","Very heavy and stores little energy, so it is only used for the 12 V system in cars."],["Solid-state (being developed)","No liquid inside, so safer; stores more energy and charges faster.","Costly and hard to make in large numbers; not yet in everyday cars."],["Sodium-ion (new)","Sodium is cheap and plentiful; works well in cold weather.","Stores less energy than lithium-ion; still at an early stage."]]},{"t":"p","en":"Your report can end with a comparison: lithium-ion batteries lead today, LFP is spreading because of its safety and price, and solid-state and sodium-ion batteries are the ones to watch. Mention recycling of used batteries as an environmental point."}]},"29cb360fe34c5def":{"t":"work","blocks":[{"t":"p","en":"A dark shadow of the hand appears on the wall. The hand is opaque and does not let light pass, and light travels in straight lines, so it cannot bend round the hand."}]},"29e1ba6b1e370c48":{"t":"work","blocks":[{"t":"h","l":4,"en":"1. The greenhouse effect and global warming: what to show"},{"t":"ul","items":[{"en":"Sunlight passes through the atmosphere and warms the Earth. The Earth gives out heat as infrared radiation."},{"en":"Greenhouse gases (carbon dioxide, methane, water vapour) trap part of this heat, as the glass of a greenhouse does; a little of this keeps the Earth warm."},{"en":"Burning fuels, cutting forests and farming add more greenhouse gases, so the Earth warms more: ice melts, seas rise and weather becomes more extreme."},{"en":"A simple model: put a thermometer in two clear jars, one with air and one filled with carbon dioxide (vinegar and baking soda), and place both in the sun. The second jar warms more."}]},{"t":"h","l":4,"en":"2. Controlling the air pollution from vehicle exhaust"},{"t":"ul","items":[{"en":"Fit catalytic converters, which change carbon monoxide, hydrocarbons and nitrogen oxides into carbon dioxide, nitrogen and water."},{"en":"Service engines regularly; use better quality fuel (low sulphur) and CNG; check the smoke of vehicles."},{"en":"Use public transport, bicycles and electric vehicles; plant trees along roads."},{"en":"Your report: how you measured (counting vehicles, checking smoke), results and which of these steps would help most."}]},{"t":"h","l":4,"en":"3. The documentaries"},{"t":"ul","items":[{"en":"The Age of Stupid (2009): a drama-documentary about what is lost if climate change is ignored."},{"en":"An Inconvenient Truth (2006): a talk on global warming, its causes and effects."},{"en":"Chasing Ice (2012): time-lapse pictures of glaciers melting."}]}]},"2bf927e47f1b1149":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Animal","Its environment"],["Fish","pond (water)"],["Ant","anthill"],["Parrot","bird's nest (in a tree)"]]}]},"2caf7f9243e9123d":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Rubbing moves electrons from the hair to the balloon, so the balloon gets a negative charge and the hair a positive charge (charging by friction)."},{"en":"When the charged balloon is brought near the wall, its charge pushes the electrons in the nearest surface of the wall away and leaves that surface positive (charging by induction)."},{"en":"Unlike charges attract, so the balloon is pulled to the wall and clings to it. The wall is not charged as a whole, but the near surface is, so the force is small and works only as long as the balloon keeps its charge (it falls when the charge leaks away, sooner in damp air)."}]}]},"2ccd3d34cad3e710":{"t":"table","rows":[["i.","sharing toys or the TV remote","sharing a bench, pens or books","children playing loudly or cricket balls going into a garden"],["ii.","who will do a chore","taking turns on the swing or in the queue","parking a vehicle in front of someone's gate"],["iii.","choosing what to eat or wear","a mistake in a game, teasing","loud music or noise at night"]]},"2da6bbbcb68efe72":{"t":"work","blocks":[{"t":"p","en":"The balance tilts towards the brick: the pan with the brick goes down. The foam is bigger but the brick has more matter packed into its space, so it has more mass and weighs more."}]},"2df840ac28976e9c":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Group 1 (plants)","Group 2 (birds)","Group 3 (reptiles)","Group 4 (mammals)"],["Rose, guava, mango, sunflower","Fowl, pigeon, sparrow, dove","Snake, crocodile, lizard, tortoise","Goat, cat, tiger, cow"]]},{"t":"p","en":"Groups are made from similar characteristics: plants make their own food; birds have feathers and wings; reptiles have dry scales and lay eggs; mammals have hair or fur and feed their young on milk."}]},"30e3ae3fc63fbca7":{"t":"work","blocks":[{"t":"p","en":"Two cotyledons. The bean seed splits into two halves; each half is a cotyledon, which stores food for the baby plant. Between them is the embryo (a tiny plumule and radicle). So the bean is a dicot seed."}]},"3108d4dfcf5f5e74":{"t":"table","rows":[["vacation","va-ca-tion","official holidays"],["protection","pro-tec-tion","to save someone from harm"],["important","im-por-tant","necessary / great value"],["strangers","stran-gers","people whom we don't know"]]},"33a2019373fcae1d":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Uncharged balloons: they neither attract nor repel; they just hang."},{"en":"Both rubbed with wool: they get the same (negative) charge and repel each other."},{"en":"One rubbed with wool and one with plastic: they get opposite charges and attract each other."},{"en":"Rule: like charges repel, unlike charges attract."}]}]},"35aa615c59f03994":{"t":"work","blocks":[{"t":"p","en":"The football occupies the most space (it has the largest volume); the pen occupies the least. Everything that is matter has weight and takes up space."}]},"35b458ea8d6e5ca4":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Switch OFF: the nail does not attract the pins."},{"en":"Switch ON: the nail attracts the pins: current in the coil makes the iron nail a magnet (an electromagnet)."},{"en":"Switch OFF again: the pins fall, because the magnetism stops with the current."}]}]},"372aea519722c832":{"t":"work","blocks":[{"t":"p","en":"The shadow of the tennis ball (Moon) falls on a small spot of the football (Earth). This is a solar eclipse: it happens when the Moon comes between the Sun and the Earth (at new moon) and its shadow falls on a part of the Earth; only the people in that shadow see the Sun covered."}]},"39be7c62af0fbc4b":{"t":"work","blocks":[{"t":"ul","items":[{"en":"North pole near north pole: they repel (the suspended magnet turns away)."},{"en":"South pole near south pole: they repel."},{"en":"North pole near south pole (opposite poles): they attract."},{"en":"Like poles repel; unlike poles attract."}]}]},"3ba4067b3700484d":{"t":"table","rows":[["safety","safe-ty","safe from injury or accident"],["cross","cross (1)","to go from one side to the other"],["image","im-age (2)","a mental picture"],["vehicle","ve-hi-cle (3)","a machine with wheels and engine"],["carelessly","care-less-ly (3)","to ignore rules"]]},"3d45ef04ff5f0ecf":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Pigeon","Butterfly"],["Body covering","feathers","scales on the wings; a hard outer skeleton"],["Backbone","has a backbone (vertebrate)","no backbone (invertebrate)"],["Legs","2","6"],["Wings","2 wings of feathers","4 wings of thin scales"],["Young ones","hatch from eggs and look like the parent","hatch as caterpillars that change shape"]]}]},"3d849dfdd56be4e5":{"t":"table","rows":[["tranquil","calm, peaceful","The lake was tranquil in the evening."],["vagrant","wanderer, drifter","A vagrant slept on the bench in the park."],["beckon","signal, call","The teacher beckoned the student to come forward."],["blessing","gift, favour","Good health is a great blessing."],["doom","fate, ruin","The storm sealed the doom of the old bridge."],["eventide","evening, dusk","The birds returned to their nests at eventide."]]},"3e0155a87f689279":{"t":"work","blocks":[{"t":"ul","items":[{"en":"The pencil stays in whatever direction it was put."},{"en":"A freely suspended bar magnet always comes to rest along the north-south direction, however many times it is disturbed: one end points to the north (the north pole) and the other to the south."}]}]},"40f2c4d72fce5adc":{"t":"work","blocks":[{"t":"h","l":4,"en":"Compounds of the alkali metals (group 1)"},{"t":"table","head":1,"rows":[["Compound","Uses"],["Sodium chloride, NaCl (common salt)","Food and preserving food; raw material for chlorine, sodium hydroxide and sodium carbonate."],["Sodium hydroxide, NaOH (caustic soda)","Making soap, paper and textiles; cleaning drains."],["Sodium carbonate, Na₂CO₃ (washing soda)","Washing clothes, softening hard water, making glass."],["Sodium hydrogencarbonate, NaHCO₃ (baking soda)","Baking, antacid for acidity, fire extinguishers."],["Potassium nitrate, KNO₃","Fertiliser, gunpowder and fireworks."],["Potassium chloride, KCl","Fertiliser (potash) for crops."],["Potassium hydroxide, KOH","Soft soap, alkaline batteries."],["Lithium carbonate, Li₂CO₃","Medicine for mood disorders, making lithium batteries."]]},{"t":"h","l":4,"en":"Compounds of the alkaline earth metals (group 2)"},{"t":"table","head":1,"rows":[["Compound","Uses"],["Calcium carbonate, CaCO₃ (limestone, marble, chalk)","Building stone, making cement, lime and glass; chalk; antacid tablets."],["Calcium oxide, CaO (quicklime)","Making cement and steel; making slaked lime."],["Calcium hydroxide, Ca(OH)₂ (slaked lime)","Whitewash, treating acidic soil and water, lime water test for carbon dioxide."],["Calcium sulphate, CaSO₄·2H₂O (gypsum)","Plaster of Paris for casts and walls, cement."],["Calcium chloride, CaCl₂","Drying agent; melting ice on roads."],["Magnesium oxide, MgO","Bricks for lining furnaces; antacid."],["Magnesium hydroxide, Mg(OH)₂ (milk of magnesia)","Medicine for acidity and constipation."],["Magnesium sulphate, MgSO₄·7H₂O (Epsom salt)","Bath salts, medicine, fertiliser."],["Barium sulphate, BaSO₄","Barium meal for X-ray pictures of the stomach; white paint."],["Strontium nitrate, Sr(NO₃)₂","Red colour in fireworks and flares."]]},{"t":"p","en":"For the classroom chart: make one chart for each group, write the name and formula of the compound in one column and its uses in the other, and draw a small picture of the product next to each."}]},"4648f8ba9a564fc9":{"t":"work","blocks":[{"t":"ul","items":[{"en":"One cotyledon (monocot seeds): wheat, rice and maize. The seed does not split into two halves."},{"en":"Two cotyledons (dicot seeds): pea, bean and gram. The seed splits easily into two halves."}]}]},"4854705bf347f8ed":{"t":"table","rows":[["rivers","tailor","aeroplane"],["forests","dentist","bicycle"],["natural gas","driver","factory"],["desert","scientist","power house"],["mountains","lawyer","tube well"]]},"49d9cd4a26aa7e47":{"t":"work","blocks":[{"t":"p","en":"The wooden piece cannot come out of the small hole because it is a solid: a solid has a fixed shape and size, and the piece is bigger than the hole."}]},"49f2dddd9f0d8acf":{"t":"table","rows":[["hair","hairs","bench","benches"],["fly","flies","knife","knives"],["tooth","teeth","book","books"],["letter","letters","potato","potatoes"]]},"4afdf6959e508c2d":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Beaker A (5 g sugar)","Beaker B (5 g starch)"],["What you see after stirring for 5 minutes","The sugar dissolves completely: a clear solution.","The starch does not dissolve: the water stays cloudy and white starch settles at the bottom."]]},{"t":"ul","items":[{"en":"1. Yes, the two beakers can be told apart by solubility: sugar is soluble in water, starch is not (it only forms a cloudy suspension)."},{"en":"2. The soluble compound is sugar. Sugars are small molecules (glucose, sucrose) that mix with water; starch is a very large polysaccharide made of thousands of glucose units, too big to dissolve."}]}]},"4b0a9bff748d8571":{"t":"work","blocks":[{"t":"p","en":"Yes, gravity is acting on the pencil all the time: it pulls the pencil down, and the thread holds it up. When the thread is broken, the pencil falls to the ground, because gravity, the pull of the Earth, draws everything towards the Earth."}]},"4b0f84483ae68b78":{"t":"work","blocks":[{"t":"p","en":"Ten elements with their symbols and a use of each. The book asks for five uses, so choose any five; if one of the elements is already in the list above it in the book, replace it by another one from the periodic table."},{"t":"table","head":1,"rows":[["Element","Symbol","Use in daily life"],["Iron","Fe","Steel for buildings, bridges, vehicles and tools"],["Copper","Cu","Electric wires and cables, cooking utensils"],["Aluminium","Al","Kitchen foil, window frames, cans, aircraft parts"],["Gold","Au","Jewellery and coins"],["Silver","Ag","Jewellery, cutlery and mirrors"],["Zinc","Zn","Coating iron sheets (galvanising) to stop rusting, dry cells"],["Sulphur","S","Matches, medicines, making sulphuric acid"],["Chlorine","Cl","Killing germs in drinking water, bleaching"],["Neon","Ne","Red-orange glowing signboards"],["Carbon","C","Pencil lead (graphite), fuel (charcoal), cutting tools (diamond)"]]}]},"4b3a50d0b17a7b7e":{"t":"work","blocks":[{"t":"h","l":4,"en":"1. Radioactive tracers in medicine"},{"t":"p","en":"A radioactive tracer is a small amount of a radioactive isotope that is swallowed, injected or breathed in. The radiation it gives out is picked up by a scanner outside the body, so doctors can see where the tracer goes and how an organ is working. Larger doses of some isotopes are used to destroy diseased cells."},{"t":"table","head":1,"rows":[["Isotope","Use"],["Technetium-99m","The most used tracer: scans of bones (fractures, spread of cancer), heart (blood flow), lungs and kidneys."],["Iodine-131","The thyroid takes up iodine, so it shows the size and working of the thyroid; a larger dose treats an overactive thyroid and thyroid cancer."],["Fluorine-18 (in a sugar called FDG)","PET scans: it collects in cells that use a lot of sugar, so it shows cancers and active areas of the brain."],["Cobalt-60","Not a tracer: its gamma rays are directed at a tumour from outside the body to treat cancer (radiotherapy)."]]},{"t":"p","en":"These isotopes are safe in small amounts because most have short half-lives (technetium-99m about 6 hours, fluorine-18 about 2 hours, iodine-131 about 8 days), so the radiation soon dies away."},{"t":"h","l":4,"en":"2. Models of Rutherford and Bohr (group work)"},{"t":"ul","items":[{"en":"Rutherford model (1911): a tiny, dense, positive nucleus in the centre, with the electrons moving around it like planets round the sun; most of the atom is empty space. Make it from a clay ball for the nucleus, wire rings and beads for the electrons, without labelled shells."},{"en":"Bohr model (1913): electrons only in fixed shells K, L, M with fixed energy. Make it with labelled rings and the number of electrons each ring can hold (2, 8, 18)."},{"en":"Share the work: group 1 makes the Rutherford model, groups 2 to 5 make Bohr models of hydrogen, carbon, sodium and chlorine."},{"en":"When presenting, compare them: Rutherford's atom could not explain why the electrons do not spiral into the nucleus; Bohr's shells did, and also explained the colours of light given out by hydrogen."}]},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 118 118\" width=\"118\" role=\"img\" aria-label=\"Bohr model of H: 1 protons, 0 neutrons, shells 1\"><circle cx=\"59\" cy=\"59\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"59.0\" cy=\"5.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"59\" cy=\"59\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"59\" y=\"55\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">1p</text><text x=\"59\" y=\"71\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">0n</text></svg>","cap":{"en":"Bohr model of hydrogen: 1 proton, 1 electron."}},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 166 166\" width=\"166\" role=\"img\" aria-label=\"Bohr model of C: 6 protons, 6 neutrons, shells 2, 4\"><circle cx=\"83\" cy=\"83\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"83.0\" cy=\"29.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83.0\" cy=\"137.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"78\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"138.2\" cy=\"27.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"138.2\" cy=\"138.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"27.8\" cy=\"138.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"27.8\" cy=\"27.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"83\" y=\"79\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">6p</text><text x=\"83\" y=\"95\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">6n</text></svg>","cap":{"en":"Bohr model of carbon: 6 protons, 6 neutrons, shells 2, 4."}}]},"52716af7b6e298a9":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Stage","Thermometer","Why"],["Ice below 0 °C is warmed","rises to 0 °C","The ice takes in heat."],["Ice melts (while ice and water are both present)","stays at 0 °C","v. No: the heat is used to break the forces that hold the molecules in the solid, not to raise the temperature."],["All the ice has melted, the water is heated","rises from 0 °C towards 100 °C","vii. The heat now makes the molecules move faster, which is the rise in temperature."],["Water boils","stays at 100 °C","The heat is used to turn water into steam."]]}]},"548f8ee91dcdf437":{"t":"work","blocks":[{"t":"p","en":"It is day on the half of the globe that faces the torch and night on the other half. As the globe turns, a place goes from day to night and back again. This shows that the rotation of the Earth on its axis (once in about 24 hours) causes day and night."}]},"57fe7405371ccb4d":{"t":"work","blocks":[{"t":"p","en":"In a neutral atom the number of protons is the atomic number and the number of electrons is the same. The number of neutrons is the mass number minus the atomic number."},{"t":"table","head":1,"rows":[["Atom","Symbol","Protons","Electrons","Neutrons","Electrons in the shells"],["Sodium","²³₁₁Na","11","11","23 − 11 = 12","2, 8, 1"],["Carbon","¹²₆C","6","6","12 − 6 = 6","2, 4"],["Oxygen","¹⁶₈O","8","8","16 − 8 = 8","2, 6"]]},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 214 214\" width=\"214\" role=\"img\" aria-label=\"Bohr model of Na: 11 protons, 12 neutrons, shells 2, 8, 1\"><circle cx=\"107\" cy=\"107\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"107.0\" cy=\"53.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107.0\" cy=\"161.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"78\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"136.8\" cy=\"34.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"179.1\" cy=\"77.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"179.1\" cy=\"136.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"136.8\" cy=\"179.1\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"77.2\" cy=\"179.1\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"34.9\" cy=\"136.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"34.9\" cy=\"77.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"77.2\" cy=\"34.9\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"102\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"107.0\" cy=\"5.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"107\" cy=\"107\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"107\" y=\"103\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">11p</text><text x=\"107\" y=\"119\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">12n</text></svg>","cap":{"en":"Sodium: 11 protons, 12 neutrons, 11 electrons in the shells 2, 8, 1."}},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 166 166\" width=\"166\" role=\"img\" aria-label=\"Bohr model of C: 6 protons, 6 neutrons, shells 2, 4\"><circle cx=\"83\" cy=\"83\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"83.0\" cy=\"29.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83.0\" cy=\"137.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"78\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"138.2\" cy=\"27.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"138.2\" cy=\"138.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"27.8\" cy=\"138.2\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"27.8\" cy=\"27.8\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"83\" y=\"79\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">6p</text><text x=\"83\" y=\"95\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">6n</text></svg>","cap":{"en":"Carbon: 6 protons, 6 neutrons, 6 electrons in the shells 2, 4."}},{"t":"svg","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 166 166\" width=\"166\" role=\"img\" aria-label=\"Bohr model of O: 8 protons, 8 neutrons, shells 2, 6\"><circle cx=\"83\" cy=\"83\" r=\"54\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"83.0\" cy=\"29.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83.0\" cy=\"137.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"78\" fill=\"none\" stroke=\"#64748b\" stroke-width=\"1.5\"/><circle cx=\"122.0\" cy=\"15.5\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"161.0\" cy=\"83.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"122.0\" cy=\"150.5\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"44.0\" cy=\"150.5\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"5.0\" cy=\"83.0\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"44.0\" cy=\"15.5\" r=\"5\" fill=\"#2563eb\"/><circle cx=\"83\" cy=\"83\" r=\"30\" fill=\"#fde68a\" stroke=\"#b45309\" stroke-width=\"2\"/><text x=\"83\" y=\"79\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">8p</text><text x=\"83\" y=\"95\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"13\" font-weight=\"700\" fill=\"#451a03\">8n</text></svg>","cap":{"en":"Oxygen: 8 protons, 8 neutrons, 8 electrons in the shells 2, 6."}},{"t":"h","l":4,"en":"How to make the model"},{"t":"ul","items":[{"en":"Take a piece of cardboard or thermocol for each atom and draw circles for the shells with a compass: two circles for carbon and oxygen, three for sodium."},{"en":"Make the nucleus in the middle from clay: one colour for the protons and another for the neutrons (sodium 11 and 12, carbon 6 and 6, oxygen 8 and 8)."},{"en":"Stick beads of a third colour on the circles for the electrons: sodium 2, 8 and 1; carbon 2 and 4; oxygen 2 and 6."},{"en":"Write the name, the symbol and the numbers of protons, electrons and neutrons under each model, and add a key to the colours."}]},{"t":"h","l":4,"en":"What to say when presenting"},{"t":"ul","items":[{"en":"Every atom is neutral: the protons (positive) and the electrons (negative) are equal in number."},{"en":"The mass of the atom sits in the nucleus, where the protons and neutrons are."},{"en":"Sodium has one electron in its outer shell and loses it easily to form Na⁺; oxygen has six and gains two to form O²⁻; carbon has four and shares them."}]}]},"5901601ae4b378c8":{"t":"work","blocks":[{"t":"p","en":"Set up as in the book: two beakers of water, calcium chloride in one, carbon dioxide blown through both with a straw."},{"t":"p","en":"SpaceBook note on the result: the usual test for carbon dioxide uses lime water (calcium hydroxide): Ca(OH)₂ + CO₂ → CaCO₃ (white, milky) + H₂O. Plain calcium chloride solution is not basic, so carbon dioxide does not turn it milky; it stays clear. If your beaker with calcium chloride stays clear, that is the correct chemistry: use lime water to see the milkiness."}]},"5a12ddccb84bfffe":{"t":"work","blocks":[{"t":"p","en":"A normal body temperature is about 98.6 °F (37 °C). A fever of 100 °F means the body temperature is 100 °F, higher than normal: the person has a mild fever, should rest, drink water and be shown to a doctor if it goes on or rises."}]},"5ada3b142b84de31":{"t":"table","rows":[["1","Ammonia","NH₃","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 100\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of ammonia\"><text x=\"65\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">N</text><circle cx=\"61.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"25\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"105\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"65\" y=\"90.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><circle cx=\"45.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.4\" cy=\"65.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"65.0\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Polar covalent: N (3.0) pulls the three shared pairs harder than H (2.1)."],["2","Water","H₂O","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of water\"><text x=\"65\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">O</text><circle cx=\"61.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"25\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"105\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><circle cx=\"45.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Polar covalent: O (3.5) pulls the shared pairs harder than H (2.1)."],["3","Hydrogen chloride","HCl","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of hydrogen chloride\"><text x=\"30\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"88\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">Cl</text><circle cx=\"84.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"91.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"84.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"91.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"103.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"103.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"59.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"59.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Polar covalent: Cl (3.0) pulls the shared pair harder than H (2.1)."],["4","Nitrogen","N₂","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of nitrogen\"><text x=\"35\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">N</text><circle cx=\"20.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"20.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"95\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">N</text><circle cx=\"110.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"110.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"58.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"58.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"65.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"65.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"72.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"72.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: two atoms of the same element share three pairs equally (triple bond)."],["5","Oxygen","O₂","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of oxygen\"><text x=\"35\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">O</text><circle cx=\"31.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"38.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"20.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"20.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"95\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">O</text><circle cx=\"91.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"98.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"110.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"110.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.5\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.5\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.5\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.5\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: two atoms of the same element share two pairs equally (double bond)."],["6","Methane","CH₄","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 92\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of methane\"><text x=\"65\" y=\"51.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">C</text><text x=\"25\" y=\"51.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"105\" y=\"51.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"65\" y=\"15.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"65\" y=\"87.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><circle cx=\"45.0\" cy=\"42.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.0\" cy=\"49.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"49.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"42.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"28.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.4\" cy=\"28.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.4\" cy=\"64.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"64.0\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: C (2.5) and H (2.1) have nearly equal pull on the pairs, and the four bonds are arranged symmetrically."],["7","Hydrogen","H₂","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of hydrogen\"><text x=\"42\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"88\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><circle cx=\"65.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"65.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: two hydrogen atoms share one pair equally."],["8","Phosphine","PH₃","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 100\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of phosphine\"><text x=\"65\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">P</text><circle cx=\"61.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"25\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"105\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><text x=\"65\" y=\"90.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">H</text><circle cx=\"45.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"85.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"61.4\" cy=\"65.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"68.6\" cy=\"65.0\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: P (2.1) and H (2.1) have almost the same pull on the shared pairs."],["9","Sulphur dioxide","SO₂","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 140 90\" width=\"140\" role=\"img\" aria-label=\"Lewis structure of sulphur dioxide\"><text x=\"28\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">O</text><circle cx=\"24.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"31.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"24.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"31.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"70\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">S</text><circle cx=\"66.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"73.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"112\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">O</text><circle cx=\"108.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"115.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"108.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"115.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"127.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"127.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.5\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"45.5\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"52.5\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"52.5\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"91.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"91.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><path d=\"M86.0 54.0 L96.0 54.0 M93.0 57.0 L96.0 54.0 L93.0 51.0\" fill=\"none\" stroke=\"#b91c1c\" stroke-width=\"1.4\"/></svg>","Polar covalent: O (3.5) pulls the shared pairs harder than S (2.5); one S to O bond is a coordinate (dative) bond."],["10","Chlorine","Cl₂","<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 130 90\" width=\"130\" role=\"img\" aria-label=\"Lewis structure of chlorine\"><text x=\"32\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">Cl</text><circle cx=\"28.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"35.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"28.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"35.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"17.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"17.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><text x=\"98\" y=\"50.5\" text-anchor=\"middle\" font-family=\"system-ui,sans-serif\" font-size=\"17\" font-weight=\"800\" fill=\"#1e3a8a\">Cl</text><circle cx=\"94.4\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"101.6\" cy=\"30.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"94.4\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"101.6\" cy=\"60.0\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"113.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"113.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"65.0\" cy=\"48.6\" r=\"2.3\" fill=\"#0f172a\"/><circle cx=\"65.0\" cy=\"41.4\" r=\"2.3\" fill=\"#0f172a\"/></svg>","Non-polar covalent: two chlorine atoms share one pair equally."]]},"5b233dd7b019e2c5":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Compound","Next homologue (one more CH₂)","Name"],["(i)","C₃H₈","C₄H₁₀","butane"],["(ii)","CH₃OH","C₂H₅OH","ethanol"],["(iii)","CH₃COOH","CH₃CH₂COOH","propanoic acid"],["(iv)","CH₄","C₂H₆","ethane"],["(v)","C₂H₅Br","C₃H₇Br","bromopropane"],["(vi)","C₃H₇NH₂","C₄H₉NH₂","butylamine"]]},{"t":"p","en":"Members of a homologous series differ by one CH₂ group, so the next member has one more carbon and two more hydrogens."}]},"5b8485f3ed64d4a0":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Raw egg","Boiled egg"],["Colour","clear egg white, yellow yolk","opaque white egg white, firm yellow yolk"],["Fluidity","runny liquid","firm solid"],["Concentration (thickness)","thick, sticky liquid","hard, set"],["pH (with pH paper)","slightly basic (about 8 to 9)","also slightly basic (little change in pH: the change is in the shape of the protein)"]]},{"t":"p","en":"Yes, the normal and the denatured protein can be told apart: heating breaks the weak bonds that hold the long protein chains in their special shape, so the chains unfold and stick together (the white turns solid and opaque). This change cannot be undone. Strong acids, alcohol and heavy metals also denature proteins."}]},"5cdedba38af0e1cc":{"t":"work","blocks":[{"t":"p","en":"The grains jump up and down very fast. Inference: sound is made by vibrations; the cone of the speaker vibrates and makes the grains vibrate."}]},"610c12290c59c49e":{"t":"table","rows":[["lugged","lugged","to pull or carry the luggage"],["stuff","stuff","belongings or things"],["promptly","prompt-ly","quickly, without delay"],["screaming","scream-ing","shouting"],["napkin","nap-kin","a small soft paper to wipe face and hands"],["ruined","ru-ined","spoiled"],["picnic","pic-nic","outing in which people take the food to eat there"]]},"61b9f937a1ec2b38":{"t":"work","blocks":[{"t":"ul","items":[{"en":"The burning candle adds air pollution (smoke and soot)."},{"en":"A black layer appears on the glass: this soot (carbon particles) is formed by the incomplete burning of the wax."},{"en":"The same happens on a large scale from vehicles, factories and burning rubbish."}]}]},"64774306e9dab9fb":{"t":"work","blocks":[{"t":"ul","items":[{"en":"After two hours the soil settles in layers."},{"en":"At the bottom: the heaviest particles, stones and gravel, then sand."},{"en":"Above them: silt and then clay, which keeps the water muddy."},{"en":"On the surface: dead leaves and bits of plants (humus), which are light and float."}]}]},"6520067e14489f37":{"t":"table","rows":[["Iodine","Non-polar","methylated spirit","Polar (an alcohol, but its C₂H₅ end is non-polar)","Yes: it dissolves, giving a red-brown solution."],["Iodine","Non-polar","water","Polar","No: only a trace dissolves, the crystals stay at the bottom."],["Vinegar","Polar","water","Polar","Yes: it mixes completely (one clear liquid)."],["Salt","Ionic","water","Polar","Yes: it dissolves completely (clear, colourless solution)."]]},"655d336f8cfe846a":{"t":"table","rows":[["tree","trees","woman","women"],["table","tables","goose","geese"],["bush","bushes","ox","oxen"],["page","pages","child","children"]]},"672312f9cf536f05":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Three layers: the shell (outside), the white and the yolk (inside)."},{"en":"The thinnest layer is the shell, on the outside; it matches the crust of the Earth."},{"en":"The biggest part is the white, which matches the mantle."},{"en":"The yolk is in the middle: it matches the core of the Earth."}]}]},"6893a9951fbcdae3":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Hydrocarbon (source)","Industrial use","Why it matters"],["Methane (natural gas, CNG)","Fuel for power stations, fertiliser factories and vehicles","Cheap, clean-burning energy"],["Propane and butane (LPG)","Cooking and heating fuel, lighters","Easy to carry in cylinders"],["Petrol and diesel","Fuel for cars, trucks, buses and generators","Move people and goods"],["Kerosene","Aircraft fuel, lamps and stoves","Air travel and lighting"],["Lubricating oil, wax and bitumen","Machine oil, candles, polish and road surfaces","Machines run smoothly; roads are built"],["Ethene and propene","Raw material for polythene, polypropylene and other plastics","Packing, pipes, bags, fibres"]]}]},"69d4b3787ea14790":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Each potato with a zinc and a copper electrode is a simple cell (about 0.8 to 1.0 volt, with very little current). The zinc is the negative electrode (it dissolves, giving electrons) and the copper is the positive one; the potato's juice (phosphoric acid and salts) is the electrolyte."},{"en":"A voltmeter across one potato shows about 0.9 V; across two in series about 1.8 V; across three in series about 2.5 V, because the voltages of cells in series add."},{"en":"A red LED needs about 1.8 to 2 V, so three potato cells in series can light it (dimly, as the current is tiny). One potato is not enough."},{"en":"Chemical energy of the zinc is changed into electrical energy, and then into light."}]}]},"6a5aeb1a451efbb4":{"t":"work","blocks":[{"t":"p","en":"With the switch ON the circuit is complete, current flows from the cell through the wires and the bulb, and the bulb glows. When the switch is turned OFF the circuit is open (broken), the current stops, and the bulb stops glowing."}]},"6b0de8bd0311da00":{"t":"work","blocks":[{"t":"p","en":"Using Fleming's left-hand rule (first finger the field, second finger the current, thumb the force), with the conventional current:"},{"t":"table","head":1,"rows":[["Panel","Magnetic field","Current","Direction of the force on the wire"],["1","into the page (×)","up","to the left"],["2","into the page (×)","down","to the right"],["3","into the page (×)","to the right","up"],["4","into the page (×)","to the left","down"],["5","out of the page (•)","up","to the right"],["6","out of the page (•)","down","to the left"],["7","out of the page (•)","to the right","down"],["8","out of the page (•)","to the left","up"]]},{"t":"p","en":"In every panel the force is at right angles to both the current and the field; turning the field or the current round turns the force round. Choose F₁ or F₂ in each panel as the one that points in the direction written above."}]},"6b25816958b00c79":{"t":"work","blocks":[{"t":"ul","items":[{"en":"The first glass (no drink) holds plain water, so it has no colour."},{"en":"The second glass (one spoon) has the lightest colour: it is the most dilute solution."},{"en":"The fifth glass (four spoons) has the darkest colour: it is the most concentrated solution."},{"en":"More solute in the same amount of water makes a more concentrated solution."}]}]},"6df6a7c7f255e7bf":{"t":"work","blocks":[{"t":"p","en":"With the switch ON the circuit is closed, so electric current flows from the cell through the wires and the bulb, and the bulb glows (electrical energy changes into light and heat). With the switch OFF the circuit is open and the bulb goes off."}]},"71dcbc379d795cc4":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Part you find","What it is","Its job"],["Two metal foils","the conducting plates","hold the opposite charges"],["A thin sheet of paper (or Mylar) between them","the dielectric (an insulator)","stops the plates touching and increases the capacitance"],["The rolled-up sandwich in a tube","compact design","gives a large plate area in a small space"]]},{"t":"p","en":"Capacitance C = Q / V, and a capacitor with large plates close together with a good dielectric stores more charge for the same voltage. Never open a capacitor that is charged or connected to a supply: it can still hold a dangerous charge."}]},"71ddb5d1d9c3f2d8":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Conductors (the bulb glows)","Insulators (the bulb does not glow)"],["aluminium foil, iron wire, copper wire, the graphite of a pencil","eraser (rubber), glass strip, plastic ruler, wood"]]},{"t":"p","en":"Metals (and graphite) allow current to pass; non-metals such as rubber, plastic, glass and wood do not."}]},"7403931996a89cb4":{"t":"work","blocks":[{"t":"ul","items":[{"en":"iv. The ice floats because ice is less dense than liquid water (about 0.92 g per cm³ against 1.00 g per cm³). In ice the water molecules are held by hydrogen bonds in an open, six-sided pattern with gaps, so the same mass takes about 9% more space."},{"en":"v. Other substances that float on water: oil, petrol, wood, cork, a plastic bottle, a leaf, a foam sheet."}]}]},"75e3cfd4875906e3":{"t":"table","rows":[["culture","cul-ture","a way of life"],["festival","fes-ti-val (3)","important days celebrated every year"],["event","e-vent (2)","local functions arranged for a group of people of the area"],["shows","shows (1)","display, to perform"],["celebrate","cel-e-brate (3)","a feeling of happiness"]]},"77f2fd3e6f736968":{"t":"work","blocks":[{"t":"p","en":"Linus Pauling (1901 to 1994) was an American chemist, born in Portland, Oregon. He used quantum mechanics to explain how atoms bond."},{"t":"table","head":1,"rows":[["Year","Work"],["1931","Paper on the nature of the chemical bond: the idea of hybrid orbitals (for example the four equal bonds of carbon) and of resonance."],["1932","Introduced the electronegativity scale (fluorine 4.0 is the highest). The difference in electronegativity tells how unequally two atoms share a pair: none gives a non-polar covalent bond, a small difference a polar covalent bond, a large difference an ionic bond."],["1939","Published the book The Nature of the Chemical Bond."],["1949 to 1951","Showed sickle-cell anaemia is a disease of one changed molecule (haemoglobin) and found the shape of protein chains (the alpha helix)."],["1954","Nobel Prize in Chemistry for his research into the nature of the chemical bond."],["1962","Nobel Peace Prize (presented in 1963) for his campaign against nuclear weapons tests."]]},{"t":"p","en":"His main point for this unit: a bond is not simply ionic or covalent; most bonds lie between the two, and electronegativity measures how far a bond is from the equal sharing of electrons."}]},"78c17c58f33bf5e1":{"t":"work","blocks":[{"t":"p","en":"A human being is born with 33 vertebrae: 7 in the neck, 12 in the chest, 5 in the lower back, 5 joined together in the sacrum and 4 joined at the tail end (coccyx). In an adult some of these have joined, so about 26 separate bones are counted."}]},"78c7193d726db7b2":{"t":"table","rows":[["i.","axe","cutting wood and hunting","cutting firewood and trees"],["ii.","plough","turning the soil for farming, pulled by oxen","still used by some farmers (most use tractors)"],["iii.","sickle","cutting wheat and grass by hand","still used to cut grass and crops in small fields"],["iv.","grinding stone (chakki)","grinding grain into flour","still used in some villages"]]},"7a871752bf34f397":{"t":"work","blocks":[{"t":"ul","items":[{"en":"1. The water flows out through the hole at the bottom and falls down: a liquid flows and has no shape of its own."},{"en":"2. When you press the soft bottle full of water, the water is not squeezed into a smaller space: it hardly changes its volume. (If the bottle has a hole, the water squirts out.)"}]}]},"7b3cdc2d5a6cb9a1":{"t":"table","rows":[["کارخانہ","کارخانے"],["جھنڈی","جھنڈیاں"],["دفتر","دفاتر"],["صفحہ","صفحات"],["ملک","ممالک"],["صابر","صابرین"]]},"7b5255df93e96e72":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Group","Observation","Type of change"],["1: steel wool burned over a spirit lamp","it glows and turns grey-black (iron oxide) and becomes heavier","chemical"],["2: blue litmus in vinegar, then in lime water","the blue litmus turns red in vinegar (an acid); a red litmus paper is turned blue by lime water (a base)","chemical (a colour change of the indicator)"],["3: paper burned","it burns with a flame and leaves black ash and smoke; it cannot be turned back into paper","chemical"],["4: yogurt added to lukewarm milk","after some hours the milk turns into yoghurt: thicker, with a sour taste","chemical (bacteria change the milk sugar)"]]},{"t":"p","en":"In a chemical change a new substance is formed and it cannot easily be changed back; in a physical change only the shape or state changes."}]},"7b7f207c99be1d57":{"t":"table","rows":[["street","spring","three","parents","first","prompt"]]},"7bf29084eb1e7dea":{"t":"work","blocks":[{"t":"p","en":"A small force on the far end of the ruler lifts the book. The ruler works as a lever, the pencil is its fulcrum (pivot) and the book is the load. The lever is easier to use when the pencil is nearer the book. A lever is a simple machine."}]},"8326fefca563d02e":{"t":"work","blocks":[{"t":"h","l":4,"en":"1. A healthy diet plan for a week (an example)"},{"t":"table","head":1,"rows":[["Day","Breakfast","Lunch","Dinner"],["Monday","Egg, chapati and milk","Lentils (daal), rice and salad","Vegetable curry, chapati and yoghurt"],["Tuesday","Porridge (daliya) with milk and a banana","Chicken, chapati and cucumber","Mixed vegetables and chapati"],["Wednesday","Paratha with a little butter and tea","Chickpeas (channa) and rice","Fish, chapati and salad"],["Thursday","Egg omelette, bread and an orange","Lentils and chapati with onion salad","Beef or mutton curry with vegetables"],["Friday","Milk, dates and a boiled egg","Vegetable pulao with raita","Daal, chapati and spinach (palak)"],["Saturday","Chapati, vegetables and lassi","Kidney beans (rajma) and rice","Chicken with vegetables and chapati"],["Sunday","Halwa puri in a small portion, milk","Mixed lentils, chapati and salad","Soup, boiled vegetables and fruit"]]},{"t":"p","en":"Each day includes carbohydrates (rice, chapati), proteins (egg, lentils, meat, milk), vegetables and fruit; little fried food, sugar and salt; and plenty of water."},{"t":"h","l":4,"en":"2. Why agricultural and nutritional sciences are vital"},{"t":"ul","items":[{"en":"Agricultural science finds ways to grow more and better food (seeds, fertilisers, protection from pests and disease) for a growing population."},{"en":"Nutritional science tells what and how much to eat for health, and how to prevent malnutrition and diseases such as anaemia, obesity and diabetes."},{"en":"Together they make sure that enough safe, nourishing food reaches everyone."}]}]},"83c0692895c29d47":{"t":"work","blocks":[{"t":"p","en":"The sugar dissolves more quickly in beaker A, the hot water. The particles of hot water move faster, so they mix with the sugar sooner: a solute dissolves faster in a hotter solvent."}]},"83e33b86a5592cea":{"t":"table","rows":[["Heart","Organ","Blood","Tissue (a fluid connective tissue)"],["C₆H₁₂O₅ (as printed)","Molecular level (a biomolecule)","Mitochondria","Organelle"],["Parenchyma","Tissue","Neuron","Cell"]]},"85d7e91d87f11218":{"t":"table","rows":[["dis-","dislike","-less","spotless"],["re-","recover","-ness","happiness"],["un-","unfriendly","-al","logical"],["in-","incorrect","-ship","friendship"]]},"86e96cbdf1d26be1":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Test tube","Conditions","Does the nail rust?"],["A","water and air","Yes, it rusts most"],["B","boiled water (no air) with oil on top","No"],["C","dry, with air only","No"]]},{"t":"p","en":"Iron rusts only when it has both water and air (oxygen). Rusting makes a new reddish-brown substance, so it is a chemical change. Painting, oiling or galvanising iron keeps water and air away."}]},"87981a3736428ee9":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Step","What you see (a muddy sample)"],["Record the sample","Cloudy, brown or yellowish water; it may smell of earth or of rotting plants."],["Add alum and stir for 4 minutes","Small flakes (floc) form and clump together."],["Let it stand (sedimentation)","The flakes sink to the bottom and the water above becomes much clearer."],["Filter through filter paper","The water that comes through is clear; the paper keeps the rest of the particles."]]},{"t":"p","en":"Filtering removes solids but not germs or dissolved salts, so water for drinking must also be boiled or chlorinated."}]},"87efb4ff60c7a673":{"t":"table","rows":[["1","Babur Azam","57","34","105","196","65.33"],["2","Fakhar Zaman","42","34","71","147","49"],["3","Muhammad Hafeez","23","85","65","173","57.67"],["4","Sarfraz Ahmed","45","12","41","98","32.67"],["5","Shoaib Malik","6","75","49","130","43.33"],["-","Maximum score","57","85","105","196","65.33"],["-","Minimum score","6","12","41","98","32.67"]]},"8a821e32f28f2f58":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Attracted by the magnet","Not attracted by the magnet"],["steel pins, iron nails, steel clips","pencil, rubber, copper wire, stone"]]},{"t":"p","en":"Magnets attract iron and steel (and nickel and cobalt); copper, rubber, wood, stone and plastic are not attracted."}]},"8aa0c7803f50905a":{"t":"work","blocks":[{"t":"p","en":"After a few hours the petals and veins of the plant standing in red ink turn pink or red; the other plant stays white. The roots took in the coloured water and the stem carried it up (through its water tubes) to the leaves and flowers. So the stem carries water from the roots to the other parts of the plant."}]},"8b7ecab30d361149":{"t":"table","rows":[["event","2 (e-vent)","something that happens, a function"],["please","1","to make someone happy; a polite word when asking"],["picnic","2 (pic-nic)","an outing in which food is taken and eaten outdoors"],["wizard","2 (wiz-ard)","a man who has magic powers"],["effort","2 (ef-fort)","an attempt; hard work"]]},"8dc37dac45925dcb":{"t":"table","rows":[["construct","constructed","constructed"],["create","created","created"],["enter","entered","entered"],["need","needed","needed"],["require","required","required"]]},"8e27b9578f909c79":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Object","Force used to change its shape"],["Plastic bottle","push (squeeze it)"],["Paper clips","pull (bend and open it out)"],["Paper","push (crumple it) or pull (tear it)"],["Toothpaste","push (squeeze the tube)"],["Rubber bands","pull (stretch it)"],["Play dough","push (press and roll it)"]]}]},"8ea211917d98bba6":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Sample","What you see with dilute sulphuric acid","What happens"],["Chalk","Bubbles of gas; the chalk wears away","Calcium carbonate gives carbon dioxide gas"],["Marble chips","Bubbles, more slowly than chalk","Calcium carbonate is slowly eaten away (buildings and statues are damaged)"],["Fresh green leaves","The leaves turn yellow-brown and dry","The acid damages the leaf tissue"],["Calcium oxide","It reacts and becomes warm","A base is neutralised by the acid; calcium sulphate is formed"],["Zinc","Bubbles of hydrogen at a steady rate","Metals above hydrogen are attacked by acids"],["Iron","A few bubbles of hydrogen, slower than zinc","The metal rusts and wears away faster in acid rain"],["Lead","Almost no reaction","A layer of lead sulphate protects the metal"]]},{"t":"p","en":"Discussion: acid rain damages limestone and marble buildings, kills leaves and trees, makes lakes acidic (fish die) and corrodes metals. It is reduced by cutting sulphur dioxide and nitrogen oxides from factories and vehicles."}]},"922bfb50f0143094":{"t":"table","rows":[["HCl","red","1"],["H₂SO₄","red","1"],["NaOH","dark blue or purple","13 to 14"],["KOH","dark blue or purple","13 to 14"],["Sugar","green","7"],["Distilled water","green","7"]]},"929750b9330ab49b":{"t":"table","rows":[["Mercury, Aluminium, Iron filings","Juice, Pizza","Water, Table Salt"]]},"9421b7fe3df7efe4":{"t":"table","rows":[["perfect","per-fect","exact, correct in every detail"],["filthy","filth-y","dirty"],["spell","spell","to say or write the letters of a word in the right order"],["decay","de-cay","to rot or go bad"],["distasteful","dis-taste-ful","having a bad taste"],["delight","de-light","great pleasure or joy"]]},"947c6eb32e1550fc":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Glass","What is added","What happens"],["A","pebbles of sand","they do not dissolve; they settle at the bottom when the water is still (a mixture)"],["B","a teaspoon of sugar","the sugar dissolves and cannot be seen; the water tastes sweet (a solution)"],["C","vegetable oil","the oil does not mix; it floats on the water as a layer"]]}]},"950bda3066856cfd":{"t":"work","blocks":[{"t":"p","en":"Natural sources of light: the Sun, the stars, lightning and the firefly. The candle and the electric bulb are made by people (artificial sources)."}]},"9595ae4b7d953e65":{"t":"work","blocks":[{"t":"p","en":"Yes: the shadow of the football (Earth) falls on the tennis ball (Moon), which goes dark. This is a lunar eclipse: it happens when the Earth comes between the Sun and the Moon and the Earth's shadow falls on the Moon (at full moon)."}]},"964dd8c3d4f63268":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Disease","Caused by","Main signs"],["Cholera","bacterium (Vibrio cholerae)","watery diarrhoea, vomiting, loss of water"],["Typhoid","bacterium (Salmonella Typhi)","long fever, headache, stomach pain"],["Dysentery","bacteria or amoeba","diarrhoea with blood"],["Hepatitis A","virus","fever, yellow eyes and skin"],["Diarrhoea","bacteria, viruses, parasites","loose stools, weakness (dangerous for small children)"]]},{"t":"h","l":4,"en":"Ways to remove them and to prevent water contamination"},{"t":"ul","items":[{"en":"Boil drinking water for at least one minute; or treat it with chlorine or purifying tablets."},{"en":"Filter and settle muddy water (cloth, sand filter, alum) before treating it."},{"en":"Keep sewage away from drinking water: covered drains, protected wells and pipes, proper toilets."},{"en":"Cover stored water, use a clean cup with a handle, and wash hands with soap before eating and after the toilet."},{"en":"Do not throw waste, factory water or pesticides into rivers, canals and ponds."}]}]},"96bbfb0d8d67b853":{"t":"table","rows":[["conserve","con-serve","save"],["resources","re-sour-ces","collective wealth of a country"],["abundance","a-bun-dance","plentiful, wealth"],["environment","en-vi-ron-ment","surrounding"],["numerous","nu-mer-ous","many, plentiful"],["effort","ef-fort","attempt"],["pollute","pol-lute","to make unclean"]]},"98d33c8a043db75d":{"t":"table","rows":[["i.","Computer","Repairing bicycle"],["ii.","Chair","Polishing shoes"],["iii.","Tractor","Teaching"],["vi.","Pencil","Examination of teeth"],["v.","Chocolate","Driving"]]},"98eff63fde4fc59d":{"t":"table","rows":[["فجر","2","-","2","-","-","-","4"],["ظہر","4","-","4","2","2","-","12"],["عصر","-","4","4","-","-","-","8"],["مغرب","-","-","3","2","2","-","7"],["عشاء","-","4","4","2","2 (اور وتر کے بعد 2)","3","17"]]},"99656ae81f141e35":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Mixture","What you should see"],["Salt in water","The grains disappear; a clear, colourless solution."],["Vinegar in water","Mixes completely; one clear liquid with the smell of vinegar."],["Iodine in water","Almost nothing dissolves; the dark crystals stay at the bottom and the water is only faintly yellow."],["Iodine in methylated spirit","The crystals dissolve; a red-brown solution."]]},{"t":"p","en":"Conclusion: like dissolves like. Salt is ionic and vinegar is polar, so both dissolve in polar water. Iodine is non-polar, so it hardly dissolves in polar water, but it dissolves in methylated spirit because the spirit's C₂H₅ part is non-polar. The results are written in the table below this activity (use its Fill the table button)."}]},"9a0445b80ffd0a2d":{"t":"work","blocks":[{"t":"p","en":"Non-luminous objects (they give no light of their own, we see them because they reflect light): the chair, the Moon, the human body and the book page. Luminous: the lighted energy saver, oil lamp, candle, firefly, stars and the Sun."}]},"9b60dc828d2738eb":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What you see: the brown bromine vapour moves out of its jar into the jar of air above it, until both jars have the same brown colour."},{"en":"Why: gas particles move all the time in every direction. Bromine particles spread out of the crowded jar into the jar that has none, and the air particles spread the other way, until they are evenly mixed. This spreading is called diffusion."},{"en":"What it proves: gases mix on their own, without stirring. Bromine vapour is much heavier than air, yet it still goes upwards, so the mixing is caused by the motion of the particles, not by weight."},{"en":"Care: bromine is poisonous and burns the skin; the teacher does this in a fume cupboard."}]}]},"9b6b5f6384887dfd":{"t":"table","rows":[["shirt, horse, dish, room, dress","long, black, sweet, clean, nice"]]},"9bc7bcbc9bd6153f":{"t":"table","rows":[["great","1","grand, bigger, larger"],["glorious","3 (glo-ri-ous)","very beautiful"],["magic","2 (mag-ic)","spell, illusion"],["whole","1","full, complete"]]},"9c8932d570a9558c":{"t":"table","rows":[["Founder","Tughril Beg","Ubayd Allah al-Mahdi","Salahuddin (Saladin)","Shah Ismail I"],["Period","1037 to 1194","909 to 1171","1171 to 1250 (Egypt)","1501 to 1736"],["Achievement","Won the battle of Manzikert against the Byzantines (1071) and united Persia, Iraq and Anatolia under Sunni rule","Founded the city of Cairo (969) and ruled Egypt, North Africa and Syria","Defeated the Crusaders at Hattin and took back Jerusalem (1187)","United Persia and made it a strong state with Twelver Shia Islam as its religion"],["Contributions 1)- 2)-","1) Nizamiyya madrasas built by Nizam-ul-Mulk 2) the Jalali calendar and an observatory under Malik Shah","1) Al-Azhar mosque and university 2) the library and House of Knowledge in Cairo","1) the Citadel of Cairo 2) madrasas and hospitals","1) the buildings of Isfahan (Naqsh-e Jahan Square, Shah Mosque) 2) Persian carpets and miniature painting"],["Causes of decline 1)- 2)-","1) quarrels among Seljuk princes 2) the rise of the Khwarazmian shahs and Mongol attacks","1) weak caliphs ruled by powerful viziers 2) the Crusades; Saladin ended the dynasty in 1171","1) quarrels among the heirs of Saladin 2) the Mamluks took power in 1250","1) weak shahs and loss of military strength 2) the Afghan invasion (1722) and trade monopolies"]]},"9e7464d1298d3342":{"t":"work","blocks":[{"t":"p","en":"The sugar in beaker A (stirred) dissolves quickly. In beaker B (not stirred) it dissolves much more slowly, because the sugar next to it is already sweet and few new water particles reach it. Stirring helps a solute dissolve faster."}]},"9fd027f7a24927c0":{"t":"table","rows":[["Archaeological ruins at Moenjodaro","Sindh","1980","Mohenjo-Daro was one of the largest cities of the Indus Valley civilisation and was the first planned city in South Asia. Located on the banks of the Indus River, it flourished between 2,500 and 1,500 BCE. The city was mostly built with baked bricks and followed a strict grid plan."],["Taxila","Punjab","1980","An ancient city of Gandhara with Buddhist monasteries and stupas and the ruins of three cities (Bhir Mound, Sirkap and Sirsukh); a famous centre of learning from about the 5th century BCE."],["Buddhist ruins at Takht-i-Bahi and the remains of Sahr-i-Bahlol","Khyber Pakhtunkhwa","1980","A hilltop Buddhist monastery of the 1st century CE near Mardan, with the ruins of the nearby fortified city of Sahr-i-Bahlol."],["Fort and Shalamar Gardens in Lahore","Punjab","1981","Lahore Fort, a royal fort of the Mughals, and the Shalamar Gardens, laid out by Shah Jahan in 1641 to 1642, are masterpieces of Mughal building and garden design."],["Historical monuments at Makli, Thatta","Sindh","1981","One of the largest burial grounds in the world, with about a million tombs of kings, saints and nobles of the 14th to 18th centuries."]]},"9fd63fed6481692e":{"t":"table","rows":[["king","queen","table","teacher"],["uncle","aunt","book","child"]]},"a0a3634b0ddacbf0":{"t":"table","rows":[["a","¹³¹₅₄Xe","54","131","54","54","77"],["b","⁵⁹₂₇Co","27","59","27","27","32"],["c","¹⁴⁴₆₀Nd","60","144","60","60","84"],["d","⁴⁸₂₂Ti","22","48","22","22","26"],["e","¹⁷⁸₇₂Hf","72","178","72","72","106"],["F","¹²⁸₅₂Te","52","128","52","52","76"],["g","⁴⁰₁₈Ar","18","40","18","18","22"]]},"a56539fb54e105e2":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Soil","Water that drips through","Water held by the soil"],["Sandy soil","most of it, quickly","least"],["Silty soil","less than sand","medium"],["Clay soil","very little, slowly","most"]]},{"t":"p","en":"Sandy soil drains fastest because its particles are large, with big gaps. Clay has the smallest particles and holds the most water."}]},"a57a5c628cd46a7e":{"t":"table","rows":[["باورچی کھانا پکاتا ہے۔","باورچی نے کھانا پکایا۔","باورچی کھانا پکائے گا۔"],["ٹھنڈی ہوا چل رہی ہے۔","ٹھنڈی ہوا چل رہی تھی۔","ٹھنڈی ہوا چلے گی۔"],["طوطا چوری کھاتا ہے۔","طوطے نے چوری کھائی۔","طوطا چوری کھائے گا۔"],["شازیہ جھولا جھولتی ہے۔","شازیہ نے جھولا جھولا۔","شازیہ جھولا جھولے گی۔"],["بچّہ روتا ہے۔","بچّہ رویا۔","بچّہ روئے گا۔"]]},"a59a769171219164":{"t":"work","blocks":[{"t":"p","en":"The end with the inflated balloon bends down, because the air inside has weight (mass), so the inflated balloon is heavier. This shows that air, a gas, has weight."}]},"a59debe445ed28aa":{"t":"work","blocks":[{"t":"ul","items":[{"en":"shrub → rat → owl"},{"en":"carrot → rabbit → fox → lion"},{"en":"grass → grasshopper → frog → snake → eagle"},{"en":"The arrow means \"is eaten by\"; every chain starts with a plant (the producer)."}]}]},"a62ddbc716218813":{"t":"work","blocks":[{"t":"p","en":"Near the bell the sound is loud. When the bell is carried away the sound becomes fainter, and further away it is very low. Inference: the intensity (loudness) of sound decreases as the distance from the source increases."}]},"a9c662dc58e3efe3":{"t":"table","rows":[["Size of Shadow","long","shortest","long"],["Direction of shadow","towards the west","very short, towards the north","towards the east"]]},"acd9cac1ecccc485":{"t":"table","rows":[["Solid","fixed shape (a stone keeps its shape)","fixed volume"],["Liquid","takes the shape of its container (water)","fixed volume"],["Gas","no shape: spreads to fill its container (air)","no fixed volume: fills all the space it gets"]]},"adb184728015158b":{"t":"work","blocks":[{"t":"p","en":"The bell gives a loud sound. If you touch the ringing bell you feel it trembling (vibrating), and when you hold it still the sound stops. So sound is made by vibrations; the energy of your hand is changed into sound energy."}]},"ae3a1861e123deef":{"t":"work","blocks":[{"t":"p","en":"Method for the soil: mix a spoon of soil with some distilled water, let it settle, dip a strip of pH paper in the clear water and compare the colour with the chart. Red or orange means acidic (pH below 7), green means neutral (7), blue or purple means basic (above 7). Most garden soils are close to neutral (pH 6 to 8)."},{"t":"table","head":1,"rows":[["Indicator","In an acidic solution","In a basic solution"],["Litmus","red","blue"],["Methyl orange","red","yellow"],["Phenolphthalein","colourless","pink"],["Universal indicator","red to yellow","blue to purple"]]}]},"b19f75deccf11e18":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Picture","Climate"],["a meadow of flowers under a cloudy sky","mild"],["snow-covered mountains","snow (cold)"],["sand dunes","desert (hot and dry)"],["dry, cracked land","dry"]]}]},"b44585cd073aa2dd":{"t":"work","blocks":[{"t":"p","en":"Loud sounds: the lion's roar, the jet plane and thunder. Low (faint) sounds: the bird, the flute and the cat."}]},"b4b3aa6b01490269":{"t":"work","blocks":[{"t":"h","l":4,"en":"a. Models of five alkanes"},{"t":"table","head":1,"rows":[["Alkane","Formula","Carbon atoms","Hydrogen atoms","A use in daily life"],["Methane","CH₄","1","4","natural gas for cooking and heating"],["Ethane","C₂H₆","2","6","raw material for making ethene and plastics"],["Propane","C₃H₈","3","8","LPG for cooking and heaters"],["Butane","C₄H₁₀","4","10","gas lighters and LPG cylinders"],["Pentane","C₅H₁₂","5","12","a solvent and a part of petrol"]]},{"t":"ul","items":[{"en":"Use black balls (or clay) for carbon and white or small balls for hydrogen. Each carbon has four single bonds; join them with sticks."},{"en":"Check each model: the number of hydrogens is always 2 × (carbons) + 2."}]},{"t":"h","l":4,"en":"b. Organic compounds and their uses"},{"t":"ul","items":[{"en":"Methane, propane, butane and petrol: fuels."},{"en":"Ethanol: solvent, disinfectant, fuel additive. Ethanoic (acetic) acid: vinegar."},{"en":"Polythene and PVC: plastic bags and pipes. Glucose, sucrose, starch: food. Soap and detergents: cleaning."},{"en":"Medicines such as aspirin and paracetamol; dyes, perfumes and fabrics such as nylon and polyester."}]},{"t":"h","l":4,"en":"c. For the class discussion"},{"t":"p","en":"Organic compounds are the basis of life (carbohydrates, proteins, fats, DNA) and of fuels, plastics, medicines and fibres. Carbon can form long chains and rings, and so makes millions of compounds. Misuse of plastics and fuels also harms the environment, so they must be used carefully."}]},"b7374ed837e816da":{"t":"work","blocks":[{"t":"ul","items":[{"en":"The dough with yeast has risen (it is bigger and full of small holes)."},{"en":"Reason: yeast is a living microorganism. It feeds on sugar and gives out carbon dioxide gas, and the gas bubbles make the dough rise."},{"en":"Sugar was added as food for the yeast. In the other pot there is no yeast, so the dough does not rise."}]}]},"b7f5bd48147747cc":{"t":"table","rows":[["communicate","com-mu-ni-cate (4)","tell, inform"],["festival","fes-ti-val (3)","fair, gala"],["gestures","ges-tures (2)","movement of the body, action, expression"],["valuable","val-u-a-ble (4)","expensive"],["aware","a-ware (2)","to know, inform"]]},"b8324f66917e76d3":{"t":"table","rows":[["mis-","mislead","-wise","clockwise"],["over-","overeat","-ful","helpful"],["pre-","preview","-ly","slowly"],["im-","impossible","-ist","artist"]]},"b96ffa1713c5bfb1":{"t":"table","rows":[["intelligent, truthful","round, oval","black, yellow","American, Chinese","large, short","few, one"]]},"ba34986ebb30deb6":{"t":"table","rows":[["Desert","cactus","camel"],["Forest","deodar (cedar) tree","monkey or deer"],["Grassland","grass","cow or buffalo"],["Polar Region","moss and lichen","polar bear or penguin"],["Fresh Water","water lily or lotus","fish (rohu) or duck"],["Salty Water","seaweed","shark, whale or crab"]]},"ba983e2a2b4f062b":{"t":"work","blocks":[{"t":"p","en":"I would drink the clean water. The muddy (turbid) water has dirt and germs in it, which cause diarrhoea, typhoid and cholera, so drinking water must be clean and, if it is not sure, boiled."}]},"bae72d231f8aa72d":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Prediction: the seeds in wet paper or cotton will also germinate, because they get water and air; a seed needs water, air and a warm temperature, not soil, to start to grow."},{"en":"In the plastic bag the seeds keep wet, so they germinate; very little air and too much water can make them rot."},{"en":"In the cup activity: the seed swells, the seed coat splits, the radicle (root) comes out first and grows downwards, then the plumule (shoot) grows upwards and leaves open in the light."}]}]},"bb47b08b9fc05225":{"t":"table","rows":[["i.","Cat (the kitten looks like its mother)","Butterfly (the caterpillar is very different)"],["ii.","Cow (the calf looks like its mother)","Frog (the tadpole is very different)"],["iii.","Human being (the baby looks like its parents)","Mosquito (the wriggler in water is very different)"]]},"bbed9cbd3a8e3f05":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Types of Pollution","Effects of Pollution"],["Air pollution","coughing, asthma and eye trouble; smog; acid rain; harms plants and animals; global warming"],["Water pollution","diseases such as cholera, typhoid and diarrhoea; fish and water plants die; water is unfit to drink"],["Land pollution","soil loses its goodness and crops grow badly; rubbish gives bad smells and breeds flies and rats; harms animals that eat it"]]}]},"bce400d6d4a19f10":{"t":"table","rows":[["hiking","swimming","paragliding","skiing"],["trekking","rowing","parasailing","snowboarding"],["bike riding, cycling, skateboarding","fishing","-","-"]]},"be7ad08fd91641e3":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Alkanes (single bonds only)","Formula","Alkenes (one C=C double bond)","Formula"],["Methane","CH₄","-","-"],["Ethane","C₂H₆","Ethene","C₂H₄"],["Propane","C₃H₈","Propene","C₃H₆"],["Butane","C₄H₁₀","Butene","C₄H₈"],["Pentane","C₅H₁₂","Pentene","C₅H₁₀"]]},{"t":"ul","items":[{"en":"Alkanes: CₙH₂ₙ₊₂. Alkenes: CₙH₂ₙ (the first alkene has two carbons, so ethene is the first alkene)."},{"en":"Use black beads for carbon and white beads for hydrogen. Join the two carbons of an alkene with two sticks (or springs) to show the double bond; every other bond is one stick."},{"en":"Show in class that an alkane carbon has four single bonds and an alkene carbon in C=C has two single bonds and one double bond."}]}]},"bef89f672dc24405":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What happens: the thin stream of water bends towards the charged balloon, without touching it."},{"en":"Why: water molecules are polar (one end is slightly positive, the other slightly negative). The negative balloon pulls the positive ends nearer and pushes the negative ends away, so the molecules are turned and the nearer, positive ends are attracted more strongly than the far ends are repelled. The net force pulls the stream towards the balloon."},{"en":"The same happens with a plastic comb rubbed on dry hair, and a positively charged object bends the stream too: it is attraction of a charged body to a neutral one, not to a charged one."}]}]},"c058a567f7b8e40c":{"t":"table","rows":[["pioneered","was the first to develop or use something new","Galileo pioneered the use of the telescope to study the sky."],["orbiting","moving around a planet or star in a curved path","The Moon is orbiting the Earth."],["monastery","a building where monks live and work","The monk lived in a monastery on the hill."],["cosmos","the universe, seen as an ordered whole","Astronomers study the cosmos with powerful telescopes."],["satellites","natural or man-made objects that move around a planet","Satellites send television and weather pictures to the Earth."]]},"c1098911ec0691c5":{"t":"table","rows":[["live","lived","to have your home in a place; to be alive"],["carry","carried","to hold something and take it from one place to another"],["prepare","prepared","to make something ready"],["require","required","to need something; to make something necessary"],["create","created","to make something new"],["hire","hired","to pay someone to work for you"],["pay","paid (irregular: not payed)","to give money for goods or work"],["enter","entered","to go or come into a place"],["skill","skilled","having the ability and training to do something well"]]},"c2a7ba977e532fa3":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Sample","What you see with bromine in CCl₄ (red-brown)","Conclusion"],["An alkene (for example ethene)","The red-brown colour quickly disappears.","It has a C=C double bond: it is unsaturated."],["An alkane (for example hexane)","The red-brown colour stays.","No double bond: it is saturated."]]},{"t":"p","en":"The alkene adds bromine across the double bond (an addition reaction): C₂H₄ + Br₂ → C₂H₄Br₂ (1,2-dibromoethane, colourless). This decolourising of bromine is the test for unsaturation."}]},"c405e9a04f5269d8":{"t":"table","rows":[["2357","-","2","3","5","7"],["67815","6","7","8","1","5"],["82301","8","2","3","0","1"],["75389","7","5","3","8","9"]]},"c5662e7c52bcf1d3":{"t":"table","rows":[["classroom","2","class-room"],["consonants","3","con-so-nants"],["clusters","2","clus-ters"],["playground","2","play-ground"],["correct","2","cor-rect"],["happy","2","hap-py"]]},"c5c546a441eea619":{"t":"table","rows":[["Solid","Heat gain","Liquid","Melting of ice cream on a hot day"],["Liquid","Heat loss","Solid","Water freezing into ice in a freezer"],["Liquid","Heat gain","Gas","Water evaporates from a puddle or a pool during a hot summer's day."],["Gas","Heat loss","Liquid","Steam turns into water drops on a cold lid or window (condensation)"]]},"c67b48ea333d09ec":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Name of the Bones","Function"],["Skull","protects the brain"],["Ribs","protect the heart and the lungs"],["Bones of Hand","hold and pick up things; help us write, lift and throw"],["Bones of Leg","hold up the body and help us walk and run"]]}]},"c68ec28e5386ca52":{"t":"table","rows":[["can be drawn into wires","Ductility","Making electric wires and cables (copper, aluminium)."],["can be bent into shape","Malleability","Beating or pressing metals into sheets and shapes: aluminium foil, utensils, car body panels."],["reflect light","Lustre (shininess)","Mirrors and jewellery (silver, aluminium, gold)."],["make a ringing sound when struck","Sonority","Bells, gongs and musical instruments."],["allow electricity to pass through","Electrical conductivity","Electric wiring and cables (copper)."],["heavy for their volume","High density","Lead weights and sinkers, ballast and balancing weights."],["transfer heat well","Thermal conductivity","Cooking pots and pans (aluminium, copper), radiators."]]},"cafc1d6428a0c07d":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Substance","Pure substance or mixture","Why"],["a","Sea water","Mixture","Water with salts and other substances dissolved in it"],["b","Cooking oil","Mixture","A blend of several fats and oils"],["c","Coal","Mixture","Carbon with other compounds and minerals"],["d","Steel","Mixture (alloy)","Iron with a little carbon"],["e","Chilli sauce","Mixture","Chillies, vinegar, salt, sugar and water"],["f","Bronze","Mixture (alloy)","Copper with tin"],["g","Sand","Mixture","Mainly silicon dioxide with small amounts of other minerals"],["h","Gold","Pure substance","An element: only gold atoms"],["i","Orange squash","Mixture","Juice, sugar, water, colour and flavour"],["j","Salt","Pure substance","A compound: sodium chloride only"],["k","Milk","Mixture","Water, fat, protein and milk sugar"],["l","Oxygen gas","Pure substance","An element: only oxygen molecules"],["m","Air","Mixture","Nitrogen, oxygen, argon, carbon dioxide and water vapour"],["n","Orange juice","Mixture","Water, sugars, acids and other substances"],["o","Coke","Mixture","Water with sugar, flavours and dissolved carbon dioxide"],["p","Soil","Mixture","Sand, clay, humus, water and air"]]},{"t":"p","en":"Pure substances: gold, salt and oxygen gas. The other thirteen are mixtures."}]},"cd129989063a63dd":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Can you see the salt in the water? No: it has dissolved (it has mixed with the water and cannot be seen), but the water tastes salty."},{"en":"After the water has evaporated, the salt is left in the dish. The salt did not change into another substance, so dissolving and evaporating are physical changes."}]}]},"d00c420989277a95":{"t":"work","blocks":[{"t":"ul","items":[{"en":"iv. After 10 minutes, if the water had suspended dirt, the water becomes clear: a jelly-like deposit settles at the bottom."},{"en":"v. Why: alum dissolves and its aluminium ions form flakes of aluminium hydroxide, which trap the suspended particles and carry them to the bottom (coagulation and sedimentation). That is why alum (phitkari) is used to clear muddy water."},{"en":"In clear water nothing much is seen except that the water becomes very slightly cloudy at first and the alum solution is slightly acidic."}]}]},"d06790e1cf7e9cd9":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What you see: the nail picks up paper pins while the current flows, and drops them when the wire is disconnected: a nail is soft iron, so it stops being a magnet when the current stops."},{"en":"Make it stronger by: more turns of wire, a larger current (another cell in series), a soft iron core, winding the turns close together."},{"en":"Poles: curl the fingers of the right hand in the direction of the current round the nail; the thumb points to the north pole (right-hand grip rule)."},{"en":"Care: the wire and the cell become hot, because a large current flows in a short wire (heating effect). Disconnect it often and do not hold it for long."}]}]},"d13eda1e0853661a":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Molar mass of CuSO₄·5H₂O = 63.6 + 32 + (4 × 16) + (5 × 18) = 249.6 g per mol."},{"en":"Mass needed for 1 dm³ of 0.5000 M solution = 0.5000 mol × 249.6 g per mol = 124.8 g."},{"en":"Weigh 124.8 g of the blue crystals on a balance and dissolve them in some water."},{"en":"Pour the solution into a 1.0 dm³ volumetric flask, rinsing the beaker into the flask so that no solute is lost."},{"en":"Add water up to the neck of the flask, stopper it and shake; then fill carefully to the 1.0 dm³ mark, put the stopper back and turn the flask over at least 10 times to mix."},{"en":"Check: 0.5000 mol in 1.000 dm³ = 0.5000 mol per dm³ = 0.5000 M."}]}]},"d361d67468484420":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What you see: a few drops of liquid bromine at the bottom of a closed jar turn into brown vapour, which slowly rises and fills the jar until the colour is the same everywhere."},{"en":"Why: the bromine particles leave the liquid, move about in the air and spread to the places where there are fewer of them. This is diffusion; it is slow because the particles keep hitting air particles."},{"en":"Conclusion: diffusion takes place in gases, and also from a liquid into a gas; the particles of matter are always moving."},{"en":"Care: only the teacher handles liquid bromine, in a fume cupboard."}]}]},"d3850438b3f657f1":{"t":"work","blocks":[{"t":"p","en":"Writing on paper is easy; on the plastic sheet the pen slips and the ink does not stay. The paper is rough, so the pen grips it (more friction); the plastic is smooth, so the pen slides over it with little friction. Friction is the force that opposes the movement of two surfaces that touch."}]},"d3c3cc2f3b289461":{"t":"table","rows":[["learn","learn","gain knowledge of or skill by studying"],["through","through","from one side to another"],["activity","ac-tiv-i-ty","a thing that a person or group does"],["poem","po-em","a piece of writing with rhythm"],["fun","fun","enjoyment, amusement, or pleasure."],["poster","pos-ter","a large printed picture used for decoration"]]},"d8b0e71e6f58e1fa":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Time","Length of the shadow","Direction"],["08:00 am","long","towards the west"],["10:00 am","shorter","towards the west"],["12:00 noon","shortest","very short (towards the north in Pakistan)"],["02:00 pm","longer again","towards the east"]]},{"t":"p","en":"Yes, the shadow changes in length and direction during the day. The Sun seems to move across the sky because the Earth rotates; when it is low the shadow is long, when it is high (noon) the shadow is shortest."}]},"d99c552c7f7f8588":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Objects","Form of Matter","End is hot or not"],["Steel Spoon","Metal","hot: metals conduct heat well"],["Plastic Scale","Plastic","not hot: plastic is a poor conductor"],["Pencil","Wood","not hot (or only slightly): wood is a poor conductor"]]}]},"d9c4aad520960d01":{"t":"work","blocks":[{"t":"p","en":"The shape of the water is different in each vessel: it takes the shape of the vessel that holds it. A liquid has no shape of its own, but its volume stays the same."}]},"da6e34fc55b315df":{"t":"work","blocks":[{"t":"p","en":"Yes, the thin wire becomes hot and melts, which breaks the circuit. A thin wire has a high resistance, so the current heats it quickly (heating effect of current). A fuse is a thin wire made on this idea: it melts first and cuts the supply when too much current flows, and so protects the appliances."}]},"dc5b4b095b9e7c3c":{"t":"work","blocks":[{"t":"p","en":"In the tug-of-war the two teams pull on the rope with the same force. The rope does not move, yet nobody is resting: both teams keep pulling all the time."},{"t":"ul","items":[{"en":"This is dynamic equilibrium: the forward and the reverse changes go on at the same rate, so nothing seems to change."},{"en":"In a reversible reaction such as N₂ + 3H₂ ⇌ 2NH₃ the rate at which ammonia forms equals the rate at which it breaks up again, so the amounts of N₂, H₂ and NH₃ stay constant."},{"en":"Equilibrium is reached only in a closed system; if one team pulls harder (a factor changes), the rope moves until a new balance is found, just as a reaction shifts when temperature, pressure or concentration is changed."}]}]},"dde8887166e77017":{"t":"table","rows":[["مثال: ۱۱","گیارھواں","گلی میں گیارھواں گھر عبداللہ کا ہے۔"],["۱۱","گیارھویں","وہ امتحان میں گیارھویں نمبر پر آیا۔"],["۱۲","بارھواں","یہ میرا بارھواں سبق ہے۔"],["۱۳","تیرھواں","ہم عمارت کی تیرھویں منزل پر رہتے ہیں۔"],["۱۶","سولھواں","کتاب کا سولھواں صفحہ کھولیں۔"],["۱۸","اٹھارھواں","اٹھارھواں سبق بہت دل چسپ ہے۔"],["۱۹","انیسواں","وہ انیسویں صدی کا مشہور شاعر تھا۔"]]},"de8a08c7287946d8":{"t":"table","rows":[["Aeroplane","Aeroplane","It carries people and goods quickly over long distances.","We would travel for days or weeks by road or ship."],["Syringe","Syringe","Doctors use it to give medicines and vaccines and to take blood.","Giving injections and vaccines would be difficult and more people would stay ill."],["Clock","Clock","It tells us the time, so we can plan school, work and prayers.","We would guess the time from the sun and often be late."],["Laptop","Laptop","A computer we can carry: we can write, study and find information anywhere.","We would work on big desktop computers or only on paper."]]},"dfb49642c63b0c41":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Glass of water: almost all the light passes through and we can see clearly across it: water is transparent."},{"en":"Glass of milk: some light passes through but we cannot see clearly across it: milk is translucent."},{"en":"A book or a wooden board: no light passes through; there is a shadow: it is opaque."}]}]},"e0a4949b47107c2f":{"t":"work","blocks":[{"t":"p","en":"The production of ammonia: N₂(g) + 3H₂(g) ⇌ 2NH₃(g), the reaction gives out heat (exothermic) and 4 moles of gas make 2 moles of gas."},{"t":"table","head":1,"rows":[["Factor","Does it affect the production?","Why"],["i. Change in temperature","Yes","The forward reaction is exothermic, so a lower temperature gives more ammonia, but a very low temperature makes it too slow; about 450 °C is the compromise."],["ii. Change in pressure","Yes","4 moles of gas become 2 moles, so a higher pressure (about 200 atmospheres) moves the equilibrium to the right and gives more ammonia."],["iii. Change in concentration","Yes","More nitrogen or hydrogen, or taking the ammonia away as it forms, shifts the equilibrium to the right."],["iv. Catalyst","Only the rate","Iron makes the equilibrium be reached faster, but it does not change the amount of ammonia at equilibrium."]]},{"t":"p","en":"So all four affect the production of ammonia, but a catalyst affects only how fast it is made, not how much."}]},"e17cd21fd4ab0f1c":{"t":"table","rows":[["rock, rope, football, vacuum cleaner, chicken","water, tomato juice, milk","smell of popcorn, air, nitrogen, hydrogen"],["sand, spoon, brick, wire","rain, sweat","steam, oxygen, smoke"]]},"e21b7ff8e905fa4c":{"t":"table","rows":[["احمد نماز ادا کرتا ہے۔","احمد نے نماز ادا کی۔","احمد نماز ادا کرے گا۔"],["میں سبق یاد کرتا ہوں۔","میں نے سبق یاد کیا۔","میں سبق یاد کروں گا۔"],["تاجر غلّہ بیچتا ہے۔","تاجر نے غلّہ بیچا۔","تاجر غلّہ بیچے گا۔"],["سخی خیرات بانٹتا ہے۔","سخی نے خیرات بانٹی۔","سخی خیرات بانٹے گا۔"],["مالی پودوں کو پانی دیتا ہے۔","مالی نے پودوں کو پانی دیا۔","مالی پودوں کو پانی دے گا۔"]]},"e401956fdb7e0ec9":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What happens: the mixture fizzes, a gas is formed and the balloon swells up and stands on the bottle."},{"en":"The reaction: citric acid (in lemon juice) + sodium hydrogencarbonate (baking soda) → sodium citrate + water + carbon dioxide gas."},{"en":"In general: acid + hydrogencarbonate → salt + water + carbon dioxide. The carbon dioxide fills the balloon."},{"en":"Proof: the gas puts out a burning splint and turns lime water milky."}]}]},"e66b979862a89025":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["","Alkyl group","Name"],["i)","CH₃CH₂CH₂–","propyl"],["ii)","CH₃CH₂–","ethyl"],["iii)","CH₃–","methyl"],["iv)","CH₃(CH₂)₂CH₂–","butyl"],["v)","CH₃(CH₂)₄CH₂–","hexyl"]]},{"t":"p","en":"An alkyl group is an alkane that has lost one hydrogen atom; its name is the alkane's name with -ane changed to -yl (butane to butyl, hexane to hexyl)."}]},"e91d54a8a3221bea":{"t":"table","rows":[["نکتہ","نِکات"],["شے","اشیا"],["دستاویز","دستاویزات"],["نعمت","نعمتیں"],["سیّارچہ","سیّارچے"],["نشان","نشانات"]]},"eb81a7caf12bfe97":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Fertiliser","Main nutrients","Class","Why it is used"],["Urea","46% nitrogen (N)","Nitrogenous","Highest nitrogen content, cheap to make and carry; makes leaves and stems grow (wheat, rice, sugarcane)"],["Calcium ammonium nitrate (CAN)","about 26% nitrogen","Nitrogenous","Less nitrogen is lost to the air; used for vegetables and fruit"],["Di-ammonium phosphate (DAP)","18% N and 46% P₂O₅","Compound (nitrogen and phosphorus)","Phosphorus helps roots and early growth; used at sowing"],["Single super phosphate (SSP)","about 18% P₂O₅ with calcium and sulphur","Phosphatic","Cheaper source of phosphorus and sulphur"],["Muriate of potash (MOP)","about 60% K₂O","Potassic","Potassium makes strong stems and good fruit and seed"],["NPK mixtures","nitrogen, phosphorus and potassium together","Compound","One application gives all three nutrients"]]},{"t":"p","en":"Each fertiliser has its own use because crops and soils need different nutrients, and because of cost, how easy it is to make, how much nutrient there is per rupee and how it reaches the farmer. Many are made like this: urea from ammonia and carbon dioxide; ammonia from nitrogen and hydrogen (Haber process); phosphate fertilisers from rock phosphate with acid."}]},"ebe511f37f7ae1aa":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Current flows from the battery through the paper clips into the coil. The coil carries current in a magnetic field of the magnet, so each side of it feels a force (Fleming's left-hand rule); the forces on the two sides are opposite, so the coil turns."},{"en":"The half of the insulation you scraped off (and the half you coloured) makes the current flow for only half of each turn. Without it the forces would reverse after half a turn and the coil would stop and swing back. The coil's own momentum carries it round through the half turn with no current, so it keeps spinning in one direction. This does the work of a commutator."},{"en":"To make it spin faster: a stronger magnet, more turns, a fresh battery. To reverse it: reverse the battery or turn the magnet over."}]}]},"ec930325833c1d1a":{"t":"table","rows":[["i.","growing crops and trees","drinking","petrol for cars and motorcycles"],["ii.","building houses, schools and roads","washing and bathing","diesel for buses, trucks and tractors"],["iii.","grazing animals, playgrounds and parks","watering the fields (irrigation)","making plastic, wax and kerosene"]]},"ed153730ac906487":{"t":"work","blocks":[{"t":"ul","items":[{"en":"What you see: when the beam hits the surface of the water from inside at a small angle of incidence, part of it comes out into the air and part is reflected. As the angle of incidence increases, the part that comes out bends further away from the normal until it just skims the surface. At an angle larger than the critical angle (about 48.6° for water), none of it comes out: all the light is reflected back into the water."},{"en":"Why: light passes from a denser medium (water) to a rarer one (air) and bends away from the normal. At the critical angle the refracted ray travels along the surface (angle of refraction 90°). Beyond it, there is total internal reflection."},{"en":"Conditions: the light must travel from the denser to the rarer medium, and the angle of incidence must be greater than the critical angle."},{"en":"Uses: optical fibres, prisms in binoculars and periscopes, diamonds' sparkle, mirages."}]}]},"ed59ae355720172c":{"t":"table","rows":[["safety","2 (safe-ty)","being safe from injury or danger"],["helmet","2 (hel-met)","a hard hat that protects the head"],["victory","3 (vic-to-ry)","winning a game or a fight"],["cheerful","2 (cheer-ful)","happy and full of joy"]]},"ee99ae102d6527ed":{"t":"work","blocks":[{"t":"p","en":"Mendeleev's table (1869) put the elements in order of atomic mass and left gaps for elements not yet found. After 1900 it became the table we use today:"},{"t":"table","head":1,"rows":[["Year","Chemist","Contribution"],["1894 to 1900","William Ramsay (with Lord Rayleigh)","Discovered the noble gases (argon, helium on Earth, neon, krypton, xenon), which added a new group at the right of the table."],["1905","Alfred Werner","Proposed the long form of the table, with the transition elements between the groups: the layout in use today."],["1913","Henry Moseley","Showed by X-ray spectra that the atomic number (number of protons), not atomic mass, fixes the order of the elements: the modern periodic law. It cured the misplaced pairs (for example argon and potassium) and showed which elements were still missing."],["1913 to 1922","Niels Bohr","His electron shells explained why elements of a group behave alike (same number of outer electrons) and why the periods end after 2, 8, 8 elements."],["1937","Carlo Perrier and Emilio Segrè","Made technetium, the first element produced artificially, filling the gap at atomic number 43."],["1940 to 1945","Glenn Seaborg","Discovered plutonium and other elements after uranium and placed the actinides in a separate row below the table, like the lanthanides; Nobel Prize 1951."],["2016","IUPAC","Approved the names nihonium (113), moscovium (115), tennessine (117) and oganesson (118), completing the seventh period: 118 elements."]]},{"t":"h","l":4,"en":"Outline of the report"},{"t":"ul","items":[{"en":"Before 1900: Döbereiner's triads (1829), Newlands' octaves (1864), Mendeleev and Meyer (1869)."},{"en":"Changes since 1900: the table above, in the order of the years."},{"en":"The table today: 118 elements in order of atomic number, 7 periods, 18 groups, and the s, p, d and f blocks."},{"en":"Conclusion: the table grew from atomic mass to atomic number and electron arrangement."}]}]},"efe169da4e522b80":{"t":"work","blocks":[{"t":"p","en":"The inflated balloons keep three different shapes. The air in each takes the shape of the balloon that holds it, so a gas has no fixed shape; it fills its container."}]},"f178edda73c0d9f6":{"t":"table","rows":[["This **cat** is chasing the **mouse**.","cat","mouse"],["There was a **man** and a **woman** at the party.","-","man, woman"],["The **dentist** will examine my **tooth**.","dentist","tooth"],["The **girls** put a **glass** and a **plate** on the **table**.","girls, glass, plate, table","-"],["My **mother** bought a **book**.","mother, book","-"]]},"f2e6e3644ab5db5a":{"t":"work","blocks":[{"t":"p","en":"On the wall or paper you see a band of seven colours in this order: red, orange, yellow, green, blue, indigo and violet (a spectrum, like a rainbow). So white sunlight is a mixture of these colours, and the prism splits it."}]},"f49ce1cd0fd49a89":{"t":"table","rows":[["fun","1","enjoyment, amusement, or pleasure"],["great","1","grand, bigger, larger"],["vacation","3 (va-ca-tion)","official holidays"],["active","2 (ac-tive)","busy and lively, doing many things"]]},"f53d58a403fe3dcb":{"t":"work","blocks":[{"t":"p","en":"Pleasant (✓): the bird's song and the harmonium. Unpleasant (×): the tractor, the braying donkey, the barking dog and the noise of traffic (noise). What is pleasant can differ from person to person, but harsh and very loud sounds are noise."}]},"f5491215b2c889a1":{"t":"work","blocks":[{"t":"ul","items":[{"en":"Alum (potassium aluminium sulphate) is used to clear water. In water it forms jelly-like flakes of aluminium hydroxide that stick to the tiny suspended particles."},{"en":"Apparatus and chemicals are as listed above; the full procedure is in the next box (Activity 14.3, continued)."}]}]},"f5e32bf95a2c12cd":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Item","Mineral it is made from"],["a ring","gold or silver"],["cooking pots","aluminium, copper or iron"],["a hand pump","iron"],["salt lamps","rock salt"],["electric cables","copper (or aluminium)"],["pottery (cups, teapot, plates)","clay"]]}]},"f67ad01602ec9122":{"t":"work","blocks":[{"t":"p","en":"The ball (Earth) is tilted, and the tilt always points the same way as it goes round the bulb (Sun). In some positions the northern half leans towards the bulb and gets more direct light (summer there); in the opposite position it leans away (winter there); in between come spring and autumn. So the Earth's yearly journey round the Sun, with its tilted axis, makes the seasons."}]},"f68c69af0bf23428":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Substance at home","Chemical","Bond"],["Table salt","NaCl","Ionic"],["Sugar","C₁₂H₂₂O₁₁","Covalent"],["Water","H₂O","Covalent"],["Copper wire","Cu","Metallic"],["Aluminium foil","Al","Metallic"],["Baking soda","NaHCO₃","Ionic (between Na⁺ and HCO₃⁻; covalent inside the HCO₃⁻ ion)"],["Cooking oil","Compounds of C, H and O","Covalent"],["Polythene bag","(C₂H₄)ₙ","Covalent"],["Iron nail","Fe","Metallic"],["Chalk or marble","CaCO₃","Ionic (between Ca²⁺ and CO₃²⁻; covalent inside the CO₃²⁻ ion)"]]}]},"f6bf97cbf0a6a619":{"t":"work","blocks":[{"t":"table","head":1,"rows":[["Substance","Type","Reason"],["CO₂","Covalent","Carbon and oxygen are both non-metals and share electrons."],["NaCl","Ionic","A metal gives an electron to a non-metal: Na⁺ and Cl⁻ ions."],["H₂O","Covalent","Hydrogen and oxygen are non-metals and share electrons."],["C₆H₆","Covalent","Carbon and hydrogen are non-metals and share electrons."],["MgCl₂","Ionic","Magnesium gives two electrons, one to each of two chlorine atoms: Mg²⁺ and 2 Cl⁻."],["HCl","Covalent","Hydrogen and chlorine share a pair of electrons (a polar covalent bond)."]]}]},"f6c559541844bcd8":{"t":"table","rows":[["victory","vic-to-ry","to win"],["defeat","de-feat","to lose"],["struggle","strug-gle","to make a lot of effort"],["sibling","sib-ling","a brother or a sister"],["cheerful","cheer-ful","very happy"],["interact","in-ter-act","to talk to some one"]]},"f74e1e697ee46a90":{"t":"table","rows":[["Numbers less than 20","12, 16, 18","15, 17, 19"],["Numbers greater than 20","28, 30, 32","21, 23, 37, 39"]]},"f826d4b512016eff":{"t":"table","rows":[["treat","1","to act or behave with a person"],["express","2 (ex-press)","to show"],["quote","1","cite, mention, tell"],["companion","3 (com-pan-ion)","friend"]]},"fa41fbd3c4b340d6":{"t":"table","rows":[["strange, thirsts","fonts, lifts, thirsts"]]},"fe16e231fcbc7411":{"t":"work","blocks":[{"t":"p","en":"In a garden soil you usually find: small living things such as ants and worms; bits of dead leaves and roots (humus); grains of sand, small stones and minerals; and some moisture that you can feel."}]}};
